const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone=x=>structuredClone(x), KEY='muxion.frontend.v1';
let db;try{db=JSON.parse(localStorage.getItem(KEY))||clone(seed)}catch{db=clone(seed)}
let role='', filter='All disciplines',courseSearch='',tab='all',lessonId='l0',playerTab='overview',cart=[],slot='',bookingDate='',media=[],pendingFiles=new Map();
db.enrolled=[];db.transactions=[];db.users=[];db.completed=[];db.quizPassed=[];db.notes={};db.comments=[];db.submissions={};db.certificates=[];db.activity=[];db.bookings=[];db.profile={...db.profile,name:'Learner',email:'',phone:'',image:''};
const loadedCourses=new Set(),loadingCourses=new Set(),courseErrors=new Map();
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(Number(n)||0);
const save=()=>{try{localStorage.setItem(KEY,JSON.stringify({...db,profile:{name:'Learner',email:'',phone:'',bio:'',timezone:db.profile.timezone,image:''},courses:db.courses.map(c=>({...c,quiz:undefined,lessons:c.lessons.map(({id,title,section,type,minutes})=>({id,title,section,type,minutes}))})),workshops:db.workshops.map(w=>({...w,meet:undefined,whatsapp:undefined})),enrolled:[],transactions:[],users:[],completed:[],quizPassed:[],notes:{},comments:[],submissions:{},certificates:[],bookings:[]}))}catch{toast('Browser storage is full. Download your demo data before adding more files.')}};
const route=currentRoute;
const go=p=>{if(route()===p)render();else navigate(p)};
const cBy=id=>db.courses.find(c=>c.id===id), wBy=id=>db.workshops.find(c=>c.id===id);
const done=c=>c.lessons.filter(l=>db.completed.includes(`${c.id}:${l.id}`)).length;
const pct=c=>c.lessons.length?Math.round(done(c)/c.lessons.length*100):0;
const paths={arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',book:'M4 4h7v16H4zm9 0h7v16h-7',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',play:'m9 5 11 7-11 7z',check:'m5 12 4 4L19 6',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',user:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',users:'M16 21v-2a6 6 0 0 0-12 0v2M14 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0m4 6a5 5 0 0 1 3 5v3M18 3a4 4 0 0 1 0 8',award:'M8 14 7 22l5-3 5 3-1-8M19 8a7 7 0 1 1-14 0 7 7 0 0 1 14 0',wallet:'M3 5h17v15H3zM3 5V3h14v2m-2 7h7v5h-7z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3m0 14v3M2 12h3m14 0h3M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',plus:'M12 5v14M5 12h14',edit:'m16 3 5 5L8 21H3v-5zM13 6l5 5',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7m4-7v7',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',external:'M14 3h7v7m0-7L10 14M10 3H3v18h18v-7',logout:'M10 3H3v18h7m4-14 5 5-5 5M8 12h13',calendar:'M3 5h18v16H3zM7 2v6m10-6v6M3 11h18',message:'M21 4H3v14h5l4 4v-4h9z',file:'M5 2h9l5 5v15H5zM14 2v6h5M8 13h8m-8 4h6',search:'M21 21l-6-6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0',menu:'M3 6h18M3 12h18M3 18h18',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z',chart:'M3 3v18h18M7 16v-5m5 5V7m5 9V4',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6zM8 12l3 3 5-6',grip:'M8 4h1m6 0h1M8 12h1m6 0h1M8 20h1m6 0h1',pause:'M8 4v16M16 4v16',mail:'M3 4h18v16H3zM3 5l9 8 9-8',globe:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0M2 12h20M12 2a18 18 0 0 1 0 20 18 18 0 0 1 0-20',phone:'M5 3h4l2 5-3 2a14 14 0 0 0 6 6l2-3 5 2v4c-10 4-22-8-16-16',image:'M3 3h18v18H3zM3 17l6-6 5 5 3-3 4 4M16 7h.01',code:'m8 6-6 6 6 6m8-12 6 6-6 6m-2-16-4 20',home:'m3 10 9-8 9 8v12h-6v-8H9v8H3z'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const link=(url,text,cls='')=>`<a href="${url}" class="${cls}" ${text.startsWith('<svg')&&!text.includes('</span>')&&!text.includes('</p>')?`aria-label="${esc(url.includes('notifications')?'Notifications':url.startsWith('/admin/courses/')?'Edit course':url.startsWith('/course/')?'Preview course':url.startsWith('/admin/workshops/')?'Edit workshop':'Open '+url.split('/').filter(Boolean).join(' '))}"`:''}>${text}</a>`;
const btn=(text,action,cls='',extra='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${extra}>${text}</button>`;
const badge=(s,color='')=>`<span class="pill ${color}">${esc(s)}</span>`;
const list=items=>`<ul class="check-list">${items.map(x=>`<li>${icon('check')}<span>${esc(x)}</span></li>`).join('')}</ul>`;
const logo=()=>{const theme=route()==='/'||route().startsWith('/build')?'build':route().startsWith('/learn')?'learning':'academy';return link('/',`<span class="wordmark" role="img" aria-label="MUXION" style="--logo-image:url('${portraits.logo}')"></span><span class="brand-label">${theme==='build'?'BUILD':theme==='learning'?'LEARN':route()==='/'?'BUILD · LEARN · ACADEMY':'ACADEMY'}</span>`,'logo')};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3600)}
const whatsapp=()=>`<a class="whatsapp" href="https://wa.me/917708100469" target="_blank" rel="noopener" aria-label="Chat with MUXION on WhatsApp">${icon('message')}</a>`;
function header(){const r=route();return `<div class="demo-bar">Design, technology & a little possibility. ${link('/contact','Say hello →')}</div><header class="nav-wrap"><div class="container nav">${logo()}<nav class="navlinks" aria-label="Main navigation">${[['/','Build'],['/learn','Learn'],['/academy','Academy'],['/about','About']].map(([p,t])=>link(p,t,((p==='/'?r==='/':r===p||r.startsWith(p+'/'))||(p==='/academy'&&['/courses','/workshops','/mentorship','/course/','/workshop/'].some(x=>r.startsWith(x))))?'active':'')).join('')}</nav><div class="nav-actions">${link('/contact',`Let’s talk ${icon('arrow')}`,'text-link')}${link(role?'/learner':'/login',role?'My portal':'Sign in','btn secondary')}${btn(icon('menu'),'mobile-menu','secondary mobile-menu','aria-label="Open navigation"')}</div></div></header>${['/academy','/courses','/course/','/workshops','/workshop/','/mentorship'].some(p=>r.startsWith(p))?`<nav class="service-subnav" aria-label="Academy navigation"><div class="container">${[['/academy','Academy home'],['/courses','Courses'],['/workshops','Live workshops'],['/mentorship','1:1 mentorship']].map(([p,t])=>link(p,t)).join('')}</div></nav>`:''}`}
function footer(){return `<footer class="footer"><div class="container"><div class="footer-top"><div>${logo()}<p>Curiosity is a good place to start.<br>Let’s see where yours takes you.</p><small>MUXION / pronounced MEEUOOOSHION</small></div><div><h4>Explore MUXION</h4>${link('/','MUXION Build')}${link('/learn','MUXION Learn')}${link('/academy','MUXION Academy')}${link('/courses','Self-paced courses')}${link('/workshops','Live workshops')}${link('/mentorship','Personal mentorship')}${link('/learn','School learning')}</div><div><h4>A little more MUXION</h4>${link('/','Build with MUXION')}${link('/about','About')}${link('/verify','Verify a certificate')}${link('/contact','Get in touch')}</div><div><h4>Let’s talk</h4><a href="mailto:hello@muxion.in">hello@muxion.in</a><a href="tel:+917708100469">+91 77081 00469</a>${link('/login/admin','Admin portal')}${link('/page-map','Explore every page ↗')}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} MUXION. Made with purpose.</span><div class="row">${link('/privacy','Privacy')}${link('/terms','Terms')}${link('/refunds','Refunds')}</div></div></div></footer>`}
const publicPage=html=>header()+`<main id="main">${html}</main>`+footer()+whatsapp();
function art(c,kind=''){return `<div class="course-art ${kind} ${c.image?'':'generated-cover'}" aria-label="${esc(c.title)}">${c.image?`<img src="${esc(c.image)}" alt="${esc(c.title)}">`:`<span class="art-label">MUXION / ${kind==='live'?'LIVE LAB':kind==='mentor'?'ONE TO ONE':'DESIGN SCHOOL'}</span><h3>Think.<br>Design.<br>Make.</h3><span class="art-bottom">YOUR NEXT CHAPTER STARTS HERE ↗</span>`}</div>`}
function courseCard(c,mode='public'){const progress=pct(c);return `<article class="card course-card">${link(mode==='learner'?'/learner/learn/'+c.id:'/course/'+c.id,art(c))}<div class="pad"><div class="between">${badge(c.category,'blue')}${btn(icon('heart'),'wishlist','secondary small',`data-id="${c.id}" aria-label="${db.wishlist.includes(c.id)?'Remove from':'Add to'} wishlist" aria-pressed="${db.wishlist.includes(c.id)}"`)}</div>${link(mode==='learner'?'/learner/learn/'+c.id:'/course/'+c.id,`<h3>${esc(c.title)}</h3>`)}<p class="muted" style="font-size:11px">${esc(c.subtitle)}</p><div class="course-meta"><span>${icon('book')} ${c.lessons.length} lessons</span><span>${icon('clock')} Lifetime access</span></div>${mode==='learner'?`<div class="between" style="font-size:10px;margin-bottom:10px"><span class="muted">${done(c)} of ${c.lessons.length} complete</span><span class="blue">${progress}%</span></div><div class="progress"><i style="width:${progress}%"></i></div><div style="margin-top:20px">${link('/learner/learn/'+c.id,`Continue learning ${icon('arrow')}`,'btn full')}</div>`:`<div class="between"><div class="price">${money(c.price)} <del>${money(c.original)}</del></div>${link('/course/'+c.id,`Explore ${icon('arrow')}`,'text-link')}</div>`}</div></article>`}
function home(){return publicPage(`<div class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow">For the endlessly curious</div><h1>Big ideas.<br>Real skills.<br><em>Your next move.</em></h1><p>Learn design by doing. Build your confidence with self-paced courses, live workshops and a mentor who’s in your corner.</p><div class="hero-ctas">${link('/courses',`Find your course ${icon('arrow')}`,'btn')}${link('/mentorship',`Meet your mentor ${icon('users')}`,'btn secondary')}</div><div class="hero-proof"><div class="avatar-stack">${testimonials.filter(t=>t.role!=='Parent').slice(0,3).map(t=>`<img src="${esc(t.image)}" alt="${esc(t.name)}, MUXION learner">`).join('')}</div><span>Personal guidance. Practical learning.<br><span style="color:#d1dbea">A little courage changes everything.</span></span></div></div><div class="hero-stage"><div class="stage-grid"></div><div class="stage-label"><span>● THE MUXION DESIGN STUDIO</span><small>OPEN TO POSSIBILITY ↗</small></div><div class="design-window"><div class="window-bar"><i></i><i></i><i></i></div><div class="window-content"><div><small>YOUR IDEAS, BROUGHT TO LIFE.</small><h3>A little curious.<br>A lot capable.</h3><div class="mini-btn">Make something great ↗</div></div><div class="orbit"><b>✳</b><i></i></div></div></div><div class="floating-tag one">${icon('spark','blue')}<div><strong>Designed by you.</strong><span class="muted">That has a nice ring to it.</span></div></div><div class="floating-tag two">${icon('check','green')}<div><strong>Less watching. More making.</strong><span class="muted">Real projects. Real progress.</span></div></div><div class="stage-bottom">LEARN / EXPERIMENT / REPEAT</div></div></section>${toolsStrip()}<section class="section"><div class="section-head"><div class="stack" style="gap:12px"><div class="eyebrow" style="margin:0">Different ways. Same possibility.</div><h2>Find your way to grow.</h2></div><p>There’s no one-size-fits-all here.<br>Choose the way you learn best.</p></div><div class="grid3">${[['01','On your time.','Self-paced courses','A little every day, or a whole weekend. Learn at your pace, with lifetime access.','/courses','book'],['02','In the room.','Live workshops','Make something alongside your community. Ask questions. Get inspired.','/workshops','spark'],['03','Just you & your mentor.','1:1 mentorship','Your goals deserve personal attention. Find clarity and build your next chapter.','/mentorship','users']].map(([n,h,t,p,url,i])=>`<a href="${url}" class="format-card"><div class="between"><span class="num">${n} / ${t.toUpperCase()}</span>${icon(i,'blue')}</div><h3>${h}</h3><p>${p}</p><span class="text-link">Explore ${t.toLowerCase()} ${icon('arrow')}</span></a>`).join('')}</div></section><section class="section" style="padding-top:0"><div class="section-head"><div><div class="eyebrow">A good place to begin</div><h2>Small steps. Standout skills.</h2></div>${link('/courses',`Explore all courses ${icon('arrow')}`,'text-link')}</div><div class="grid3">${db.courses.filter(c=>c.status==='Published').slice(0,3).map(c=>courseCard(c)).join('')}<a class="card" href="/workshops"><div class="course-art live generated-cover"><span class="art-label">MUXION / LIVE WORKSHOP</span><h3>Make it<br>together.</h3><span class="art-bottom">LEARN LIVE WITH MARIAM ↗</span></div><div class="pad">${badge('Live workshop','blue')}<h3 style="margin:16px 0">The Live Design Lab</h3><p class="muted" style="font-size:12px">One focused session. A fresh perspective.</p><div class="between" style="margin-top:24px"><span class="price">${money(db.workshops[0]?.price)}</span><span class="text-link">Save your seat ${icon('arrow')}</span></div></div></a><a class="card" href="/mentorship"><div class="course-art mentor generated-cover"><span class="art-label">MUXION / PERSONAL MENTORSHIP</span><h3>Your goals.<br>Our focus.</h3><span class="art-bottom">A DESIGNER IN YOUR CORNER ↗</span></div><div class="pad">${badge('1:1 mentorship','green')}<h3 style="margin:16px 0">A path that’s entirely yours</h3><p class="muted" style="font-size:12px">Portfolio feedback. Practical direction. You.</p><div style="margin-top:24px" class="text-link">Meet your mentor ${icon('arrow')}</div></div></a></div></section><section class="section" style="padding-top:0"><div class="feature-band"><div><div class="eyebrow">Introducing MUXION Momentum</div><h2>Find your focus.<br>Feel your progress.</h2><p>45 minutes of learning. 15 minutes to reset. Make space for your next skill with a learning rhythm that works for you.</p>${link('/learner/momentum',`Meet your new learning ritual ${icon('arrow')}`,'text-link')}</div><div><div class="momentum-circle"><strong>45:00</strong><small>ONE GOOD FOCUS SESSION</small></div><p style="text-align:center;font-size:10px;margin:20px 0 0">A little focus. A little reset. One step forward.</p></div></div></section><section class="section" style="padding-top:0"><div class="tutor-banner"><div class="academy-mentor-photos"><figure class="academy-mentor-main"><img src="assets/people/mariam-academy-teaching.jpeg" alt="Mariam Parvez explaining ideas during an in-person teaching session" loading="lazy" decoding="async" width="1454" height="1201"><figcaption><strong>Mariam Parvez</strong><span>Designer. Developer. Your next mentor.</span></figcaption></figure><figure class="academy-mentor-detail"><img src="assets/people/mariam-academy-session.jpeg" alt="Mariam Parvez leading a session beside a projection screen" loading="lazy" decoding="async" width="766" height="1201"></figure></div><div><div class="eyebrow">Real experience. Human connection.</div><h2>Good design starts<br>with good guidance.</h2><p>I’m Mariam. For ${experienceYears()}+ years, I’ve turned complex problems into thoughtful digital experiences. Today, I combine design, development and AI to build full-stack products—and help you find your own way to create.</p>${list(['Practical skills, grounded in real projects','Personal feedback that moves you forward','A learning space for every kind of curious'])}<div style="margin-top:24px">${link('/about',`A little more about me ${icon('arrow')}`,'text-link')}</div></div></div></section><section class="section" style="padding-top:0"><div class="section-head"><div><div class="eyebrow">From the MUXION community</div><h2>In their own words.</h2></div><span class="muted" style="font-size:11px">Learner stories from your original MUXION site.</span></div>${testimonialSlider(testimonials)}</section><section class="section" style="padding-top:0"><div class="build-teaser">${buildGraphic()}<div class="eyebrow">Build with MUXION</div><h2>You have the idea.<br>Let’s make it happen.</h2><p>A website, app, or that software idea you keep thinking about. From first sketch to full-stack launch, let’s build something that moves your world.</p>${link('/',`LET’S COLLABORATE ${icon('arrow')}`,'btn')}</div></section></div>`)}
function catalogue(){const courses=db.courses.filter(c=>c.status==='Published'&&(filter==='All disciplines'||c.category===filter)&&c.title.toLowerCase().includes(courseSearch.toLowerCase()));return publicPage(`<div class="container"><div class="page-hero"><div class="eyebrow">The next version of you</div><h1>Follow your curiosity.</h1><p>UI/UX, graphic design, animation, art or your first line of code.<br>Make room for the skills you’ve always wanted.</p></div><section class="section" style="padding-top:16px"><div class="toolbar"><input id="course-search" type="search" placeholder="Search courses…" aria-label="Search courses" value="${esc(courseSearch)}">${badge(`${courses.length} course${courses.length===1?'':'s'}`)}</div><div class="subnav">${topics.map(t=>btn(esc(t),'filter','chip'+(filter===t?' active':''),`data-value="${esc(t)}"`)).join('')}</div>${courses.length?`<div class="grid3">${courses.map(c=>courseCard(c)).join('')}</div>`:empty('Your next skill is on its way.','No published courses match this selection. Try another discipline.','Explore all courses','/courses','book')}<div class="notice" style="margin-top:32px">The original archive confirms courses starting at ₹299. The UI/UX Mastery course is seeded for this preview; its curriculum and other offer prices are editable draft content.</div></section></div>`)}
function courseDetail(id){const c=cBy(id);if(!c||c.status!=='Published')return notFound();const groups=[...new Set(c.lessons.map(l=>l.section))];return publicPage(`<div class="container section"><div class="breadcrumb">${link('/courses','Courses')} / ${esc(c.category)} / Mastery</div><div class="detail-grid"><div class="detail-main"><div class="detail-intro"><div class="row">${badge('SELF-PACED','blue')}${badge(c.level)}</div><h1 class="detail-title">${esc(c.title)}<br><span class="blue">${esc(c.subtitle)}</span></h1><p class="detail-description">${esc(c.description)}</p><div class="row"><img class="avatar" src="${portraits.mariam}" alt="Mariam"><div><small>Created & taught by <strong>${esc(c.tutor)}</strong></small><p class="muted" style="font-size:10px">${experienceYears()}+ years in UI/UX design & development</p></div></div><div class="course-meta"><span>${icon('globe')} ${esc(c.language)}</span><span>${icon('book')} ${c.lessons.length} lessons</span><span>${icon('award')} Certificate included</span></div></div><section class="detail-section"><h2>From “I wonder” to “I made this.”</h2><div class="outcomes">${list(c.outcomes.slice(0,Math.ceil(c.outcomes.length/2)))}${list(c.outcomes.slice(Math.ceil(c.outcomes.length/2)))}</div></section><section class="detail-section"><div class="between"><h2>Inside your course.</h2>${btn('Expand all','expand-all','secondary small')}</div><p class="muted" style="font-size:11px">${groups.length} chapters · ${c.lessons.length} lessons · ${c.lessons.reduce((s,l)=>s+Number(l.minutes),0)} minutes of guided learning</p>${groups.map((g,i)=>`<details class="accordion" ${i===0?'open':''}><summary><span>${String(i+1).padStart(2,'0')} &nbsp; ${esc(g)}</span><small>${c.lessons.filter(l=>l.section===g).length} lessons</small></summary>${c.lessons.filter(l=>l.section===g).map((l,j)=>`<div class="lesson-row">${icon(l.type==='video'?'play':l.type==='quiz'?'spark':'file')}<span class="grow">${esc(l.title)}</span>${i===0&&j===0?btn('Preview','preview-lesson','secondary small',`data-course="${c.id}" data-id="${l.id}"`):''}<small>${l.minutes} min</small></div>`).join('')}</details>`).join('')}</section><section class="detail-section"><h2>Is this your next chapter?</h2><p class="muted">${esc(c.audience)}</p><h3 style="margin:24px 0 12px">What you’ll need</h3><p class="muted">${esc(c.requirements)}</p></section><section class="detail-section"><h2>Your mentor, Mariam.</h2><div class="row"><img class="avatar large" src="${portraits.mariam}" alt="Mariam"><p class="muted" style="font-size:12px">UI/UX designer, developer and founder of MUXION. ${experienceYears()}+ years of making digital experiences and helping curious people become confident creators.</p></div></section>${faq()}</div><aside class="card detail-buy">${art(c)}<div class="pad"><div class="price">${money(c.price)} <del>${money(c.original)}</del></div><p class="muted" style="font-size:10px;margin:12px 0 24px">One payment. A lifetime of possibility.</p>${db.enrolled.includes(c.id)&&currentUser?link('/learner/learn/'+c.id,`Continue learning ${icon('arrow')}`,'btn full'):btn(`Make this your next move ${icon('arrow')}`,'add-cart','full',`data-id="${c.id}"`)}<div style="margin:12px 0 24px">${btn('Save for later','wishlist','secondary full',`data-id="${c.id}"`)}</div>${list(['Lifetime course access','Video lessons & practical resources','Quizzes, notes & community discussions','Certificate in PDF, PNG and JPG','MUXION Momentum focus rewards'])}<p class="form-note" style="margin-top:20px">Preview curriculum. Original video files are not present in the supplied archive; lessons will show a clear unavailable state until added.</p></div></aside></div></div>`)}
function faq(){return `<section class="detail-section"><h2>A few things you might wonder.</h2>${db.faqs.map(f=>`<details class="accordion"><summary>${esc(f.q)}</summary><p class="pad muted" style="font-size:12px">${esc(f.a)}</p></details>`).join('')}</section>`}
function workshops(){return publicPage(`<div class="container"><div class="page-hero"><div class="eyebrow">A little live energy</div><h1>Make it together.</h1><p>Focused workshops. Fresh perspectives. A chance to ask the question that’s been on your mind.</p></div><section class="section" style="padding-top:16px"><div class="grid2">${db.workshops.filter(w=>w.status==='Published').map(w=>`<article class="card">${art(w,'live')}<div class="pad"><div class="between">${badge('LIVE WORKSHOP','blue')}${badge(w.recording?'Recording included':'Live only')}</div><h3 style="font-size:26px;margin:20px 0 12px">${esc(w.title)}</h3><p class="muted" style="font-size:12px">${esc(w.topic)}</p><div class="course-meta"><span>${icon('calendar')} ${formatWorkshop(w)}</span><span>${w.duration} min</span></div><div class="between"><div class="price">${money(w.price)} <del>${money(w.original)}</del></div>${link('/workshop/'+w.id,`Explore workshop ${icon('arrow')}`,'btn')}</div></div></article>`).join('')||empty('More good things are coming.','The next workshop will appear here when your tutor publishes it.','Explore courses','/courses','calendar')}</div></section></div>`)}
function formatWorkshop(w){return `${new Date(w.date+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})} · ${w.time} · ${w.timezone}`}
function workshopDetail(id){const w=wBy(id);if(!w||w.status!=='Published')return notFound();return publicPage(`<div class="container section"><div class="breadcrumb">${link('/workshops','Workshops')} / ${esc(w.title)}</div><div class="detail-grid"><div><div class="eyebrow">Live, with MUXION</div><h1 class="detail-title">${esc(w.title)}</h1><p class="detail-description">${esc(w.topic)}</p><div class="row wrap">${badge(formatWorkshop(w),'blue')}${badge(w.duration+' minutes')}${badge(w.capacity+' seats')}</div><section class="detail-section"><h2>Here’s what we’ll make room for.</h2>${list(w.pointers)}</section><section class="detail-section"><h2>Meet your tutor.</h2><div class="row"><img class="avatar large" src="${esc(w.photo)}" alt="${esc(w.tutor)}"><div><h3>${esc(w.tutor)}</h3><p class="muted" style="font-size:12px">${esc(w.bio)}</p></div></div></section><div class="notice">Your account receives workshop access after verified payment. Your tutor will publish the private joining details when they are ready.</div>${faq()}</div><aside class="card detail-buy">${art(w,'live')}<div class="pad"><div class="price">${money(w.price)} <del>${money(w.original)}</del></div><p class="muted" style="font-size:11px;margin:16px 0">${formatWorkshop(w)}</p>${btn(`Save my seat ${icon('arrow')}`,'workshop-checkout','full',`data-id="${w.id}"`)}<div class="divider"></div>${list(['Live interaction with your tutor',w.recording?'Workshop recording included':'An entirely live experience','Resources and guided exercises','Private workshop community'])}</div></aside></div></div>`)}
function mentorship(){return publicPage(`<div class="container"><section class="hero"><div class="hero-copy"><div class="eyebrow">1:1 mentorship, made personal</div><h1>Your goals.<br>Your pace.<br><em>Your person.</em></h1><p>Get unstuck, find your direction and build the work you want to be known for. A real conversation can change a lot.</p><div class="hero-ctas">${link('/mentorship/book',`Find a time to talk ${icon('calendar')}`,'btn')}${btn('Ask a question','enquiry','secondary')}</div><a class="text-link" href="https://wa.me/917708100469" target="_blank" rel="noopener">Let’s start on WhatsApp ${icon('external')}</a></div><div class="tutor-photo"><img src="${portraits.mariam}" alt="Mariam, your personal design mentor"><div class="caption"><strong>Mariam Parvez</strong><p style="font-size:11px;margin:4px 0 0">${experienceYears()}+ years of design & development. Here for your next chapter.</p></div></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">A little structure. A lot of you.</div><h2>Make your next move with clarity.</h2></div></div><div class="grid3">${db.mentorships.filter(m=>m.status==='Published').map(m=>`<article class="card pad">${badge('PERSONAL SESSION','green')}<h3 style="margin:24px 0">${esc(m.title)}</h3><p class="muted" style="font-size:12px;margin-bottom:24px">${esc(m.description)}</p>${list(m.pointers)}<div class="divider"></div><div class="between"><div class="price">${money(m.price)}<p class="muted" style="font-size:10px;font-weight:400">${m.duration} minutes · 1:1</p></div>${link('/mentorship/book',`Book a session ${icon('arrow')}`,'btn')}</div></article>`).join('')}<article class="card pad"><div class="eyebrow">Longer-term growth</div><h3>A roadmap, together.</h3><p class="muted" style="font-size:12px;margin:24px 0">Build a personal mentorship package around your goals, availability and starting point.</p>${list(['A discovery conversation','A plan tailored to your goals','A quote before you commit'])}<div style="margin-top:32px">${btn(`Explore a package ${icon('arrow')}`,'enquiry','secondary')}</div></article><article class="card pad"><div class="eyebrow">Not sure where to start?</div><h3>That’s a good question.</h3><p class="muted" style="font-size:12px;margin:24px 0">Tell me where you are and where you’d like to go. We’ll figure out a good first step.</p><a href="https://wa.me/917708100469" class="btn secondary" target="_blank" rel="noopener">Talk on WhatsApp ${icon('message')}</a></article></div></section>${faq()}</div>`)}
function booking(){const m=db.mentorships.find(x=>x.status==='Published');if(!m)return notFound();return publicPage(`<div class="container section"><div class="breadcrumb">${link('/mentorship','Mentorship')} / Find your time</div><div class="detail-grid"><div><div class="eyebrow">Let’s make a little time</div><h1 class="detail-title">Your next conversation.</h1><p class="muted">Choose a preferred date and time. Overlapping requests are checked before your session is saved.</p><form id="booking-form" class="stack" style="margin-top:32px"><label>Your name<input name="name" required value="${esc(db.profile.name)}"></label><label>Email address<input name="email" type="email" readonly required value="${esc(db.profile.email)}"></label><label>Preferred date<input name="date" type="date" required min="${new Date().toLocaleDateString('en-CA')}" value="${esc(bookingDate)}"></label><label>Preferred time · Asia/Kolkata<select name="time" required><option value="">Select a time</option>${['10:00','11:30','14:00','16:30','18:00'].map(s=>`<option ${slot===s?'selected':''}>${s}</option>`).join('')}</select></label><label>What would you like to work on?<textarea name="goals" required placeholder="Your project, portfolio, career questions…"></textarea></label><button class="btn" type="submit">Request this session ${icon('arrow')}</button></form></div><aside class="card pad detail-buy"><img class="avatar large" src="${portraits.mariam}" alt="Mariam"><h3 style="margin:24px 0">${esc(m.title)}</h3><p class="muted">${m.duration} minutes · Google Meet</p><div class="price" style="margin:24px 0">${money(m.price)}</div><div class="notice">No payment is collected at this step. Your mentor will confirm the request and arrange payment separately.</div></aside></div></div>`)}
function buildPage(){return publicPage(`<div class="build-page"><div class="container"><section class="build-hero"><div class="build-intro"><div class="build-intro-copy"><div class="eyebrow">Build with MUXION / Ideas welcome.</div><h1>You dream it.<br>We <span>make it real.</span></h1><div class="build-intro-actions"><p>A website. An app. Software that makes your day easier. From first “what if” to fully developed and deployed—with design, code and AI working together.</p>${btn(`LET’S COLLABORATE ${icon('arrow')}`,'build-enquiry','yellow')}</div></div>${buildHeroGraphic()}</div></section><section class="section"><div class="section-head"><h2>A good idea has<br>no industry limit.</h2><p>For founders, freelancers, local businesses and teams. If you need it, let’s talk about building it.</p></div><div class="grid3">${[['globe','Websites that do more.','From a sharp first impression to a complete e-commerce experience.'],['code','Apps with a purpose.','Web apps, dashboards, portals and tools shaped around the way you work.'],['spark','Software, your way.','Fintech, accounts, marketing, operations or an entirely new idea.']].map(([i,t,p])=>`<article class="format-card">${icon(i,'yellow')}<h3>${t}</h3><p>${p}</p></article>`).join('')}</div></section><section class="section"><div class="tutor-banner"><div class="tutor-photo build-founder-photo"><img src="assets/people/mariam-build-founder.jpg" alt="Mariam Parvez, MUXION designer and developer" loading="lazy" decoding="async" width="585" height="438"></div><div><div class="eyebrow">Meet your builder</div><h2>Design thinking.<br>Full-stack doing.</h2><p>I’m Mariam. With ${experienceYears()}+ years in UI/UX design and development, I bring the entire picture together. I use AI to move from thoughtful design to full-stack development and deployment, with one person owning the journey.</p><div class="about-metrics"><div><strong>${experienceYears()}+</strong><small>Years of experience</small></div><div><strong>01</strong><small>Partner, start to launch</small></div></div>${btn(`Tell me what’s on your mind ${icon('arrow')}`,'build-enquiry','yellow')}</div></div></section>${clientExperience(icon)}<section class="section"><div class="build-teaser"><div class="eyebrow">There’s room for your idea here</div><h2>Let’s make something<br>worth putting into the world.</h2><div style="margin-top:28px">${btn(`LET’S COLLABORATE ${icon('arrow')}`,'build-enquiry')}</div></div></section></div></div>`)}
function buildHomeSections(){const page=buildPage(),start=page.indexOf('<section class="section">'),end=page.lastIndexOf('</div></div></main>');return `<div class="build-page"><div class="container">${page.slice(start,end)}</div></div>`}
function learning(){return publicPage(`<div class="container"><section class="learning-hero"><div><div class="eyebrow">MUXION Learning / Grades 9–12</div><h1>Less “I don’t get it.”<br><span class="blue">More “I’ve got this.”</span></h1><p>Maths, Physics and Chemistry with people who make room for every question. Personal guidance for A Levels, State Board, CBSE and IGCSE learners.</p><div class="learning-contact-actions"><a class="btn" href="https://wa.me/917708100469?text=Hi%20MUXION%2C%20I%E2%80%99d%20like%20to%20know%20more%20about%20MUXION%20Learning%20for%20grades%209%E2%80%9312." target="_blank" rel="noopener noreferrer">${icon('message')} Contact now</a><a class="btn secondary" href="tel:+917708100469">${icon('phone')} Call us</a></div></div><div class="tutor-pair"><div class="tutor-tile"><img src="${portraits.yaseen}" alt="Syed Yaseen"><span>SYED YASEEN<br><small>Your learning guide</small></span></div><div class="tutor-tile"><img src="${portraits.farzana}" alt="Farzana Shaheen"><span>FARZANA SHAHEEN<br><small>Your learning guide</small></span></div></div></section><section class="section learn-tutors"><div class="section-head"><div><div class="eyebrow">MEET YOUR TUTORS</div><h2>Deep experience.<br>Strong foundations.</h2></div><p>Learn from educators with substantial classroom, academic and mentoring experience.</p></div><div class="learn-tutor-grid"><article class="learn-tutor-card"><div class="learn-tutor-portrait"><img src="${portraits.farzana}" alt="Farzana Shaheen, MUXION tutor" loading="lazy" decoding="async"></div><div class="learn-tutor-copy"><div class="eyebrow">22+ YEARS IN EDUCATION</div><h3>Farzana Shaheen</h3><p class="learn-tutor-lead">Top teacher across A Levels, State Board, CBSE and IGCSE, with 22+ years in education.</p><p>Across 22+ years, Farzana has served as a teacher coordinator, supervisor, principal and teacher. Her experience spans classroom teaching and school leadership.</p><div class="learn-tutor-credentials"><span>M.Sc.</span><span>B.Ed.</span><span>B.Sc. Zoology</span></div></div></article><article class="learn-tutor-card"><div class="learn-tutor-portrait"><img src="${portraits.yaseen}" alt="Syed Yaseen, MUXION tutor" loading="lazy" decoding="async"></div><div class="learn-tutor-copy"><div class="eyebrow">MATHS & PHYSICS MENTOR</div><h3>Syed Yaseen</h3><p class="learn-tutor-lead">A school topper with exceptional marks in Maths and Physics, who has already taught 10 students.</p><p>Yaseen pairs strong subject foundations with a practical, structured approach to helping students understand challenging concepts.</p><div class="learn-tutor-credentials"><span>B.E. · ECE · KCG College of Technology</span><span>MBA · Supply Chain & Logistics · BITS Pilani, Goa</span></div></div></article></div></section><section class="section"><div class="section-head"><h2>Strong foundations.<br>Brighter possibilities.</h2><p>Build understanding before memorising answers. A little clarity makes a big difference.</p></div><div class="grid3">${[['Maths','From equations to “of course.”','4499','∑'],['Physics','Understand the why behind the world.','4499','↗'],['Chemistry','Make the connections that click.','4499','⚗']].map(([t,p,n,s])=>`<article class="card pad subject-card" data-subject="${t}"><div class="subject-art">${subjectGraphic(t)}</div><span class="subject-icon" aria-hidden="true">${icon(t==='Maths'?'chart':t==='Physics'?'spark':'code')}</span><h3 style="margin:20px 0 12px">${t}</h3><p class="muted" style="font-size:12px">${p}</p><div class="subject-pricing" style="margin:24px 0"><p class="muted" style="font-size:13px;margin-bottom:8px"><span class="sr-only">Original price </span><del>₹10,999</del> / month</p><p class="price">${money(n)}<small class="muted" style="font-weight:400"> / month</small></p></div><div class="learning-contact-actions stacked"><a class="btn full" href="https://wa.me/917708100469?text=Hi%20MUXION%2C%20I%E2%80%99d%20like%20to%20know%20more%20about%20${encodeURIComponent(t)}%20tuition%20for%20grades%209%E2%80%9312." target="_blank" rel="noopener noreferrer" aria-label="Contact now about ${t} on WhatsApp">${icon('message')} Contact now</a><a class="btn secondary full" href="tel:+917708100469" aria-label="Call MUXION about ${t}">${icon('phone')} Call us</a></div></article>`).join('')}</div><p class="form-note" style="margin-top:20px">Monthly tuition for grades 9–12. Contact us on WhatsApp or call +91 77081 00469 to discuss your board, subjects and learning plan.</p></section><section class="section"><div class="feature-band tutor-feature"><div><div class="eyebrow">Two tutors. A shared purpose.</div><h2>Syed Yaseen &<br>Farzana Shaheen.</h2><p>Helping students in grades 9–12 find confidence in Maths, Physics and Chemistry. Start a conversation to discuss your board, subjects and learning needs.</p><div class="learning-contact-actions"><a class="btn" href="https://wa.me/917708100469?text=Hi%20MUXION%2C%20I%E2%80%99d%20like%20to%20know%20more%20about%20MUXION%20Learning%20for%20grades%209%E2%80%9312." target="_blank" rel="noopener noreferrer">${icon('message')} Contact now</a><a class="btn secondary" href="tel:+917708100469">${icon('phone')} Call us</a></div></div><div class="tutor-band-right"><div class="tutor-montage"><figure><img src="${portraits.yaseen}" alt="Syed Yaseen"></figure><figure><img src="${portraits.farzana}" alt="Farzana Shaheen"></figure><span class="montage-label">TWO GUIDES. ONE BRIGHTER NEXT CHAPTER.</span></div>${list(['Grades 9, 10, 11 and 12','CBSE & State Board support','A focus on understanding concepts','A plan for your learning needs'])}</div></div></section></div>`)}
function about(){return publicPage(`<div class="container section"><div class="tutor-banner"><div class="tutor-photo"><img src="${portraits.mariam}" alt="Mariam Parvez"></div><div><div class="eyebrow">The person behind the possibility</div><h1 class="detail-title">Hi, I’m Mariam.<br><span class="blue">Let’s make things.</span></h1><p>I’m a Design Manager with ${experienceYears()}+ years of experience in UI/UX design and development. MUXION brings together what I love: creating digital experiences and helping others discover what they can do.</p><p>From your first design lesson to a fully developed and deployed app, there’s room for your ambition here.</p><div class="row">${link('/mentorship','Learn with me','btn')}${link('/','Build with me','btn secondary')}</div></div></div>${clientExperience(icon)}<section class="about-motherhood section" aria-labelledby="motherhood-title"><figure class="motherhood-photo"><img src="assets/people/mariam-family.webp" width="1350" height="1800" loading="lazy" decoding="async" alt="Mariam holding her son as they enjoy a quiet moment together"><figcaption><span>A MOMENT FROM MY WORLD</span><strong>My little boy.<br>My biggest why.</strong></figcaption></figure><div class="motherhood-story"><div class="motherhood-kicker"><span class="motherhood-spark" aria-hidden="true">✳</span> A little more personal <span class="motherhood-number" aria-hidden="true">01 / ME</span></div><h2 id="motherhood-title">Building a dream.<br><span>Raising my reason.</span></h2><p class="motherhood-intro">Beyond the screens and sketches, I’m mommy to a wonderfully naughty little toddler. The smallest person in my world, and my biggest reason to keep going.</p><p>Life is a beautiful juggle of little hands reaching for me and big dreams asking me to be brave. I don’t always get the balance right, but I keep showing up, with love for my son and a heart that still has so much it wants to create.</p><p>Everything I’m building carries a hope for him. In sha Allah, one day he’ll look at my journey and see a mother who worked hard, believed in her dreams and kept going. And when it’s his turn to chase something that matters, I hope he’ll carry that same courage, dedication and heart into his own story.</p><div class="motherhood-signature"><span>Mariam</span><small>A mother. A maker. Still dreaming.</small></div></div></section><section class="section"><h2>Good work starts with people.</h2>${testimonialSlider(testimonials)}</section></div>`)}
function contact(){return publicPage(`<div class="container section"><div class="detail-grid"><div><div class="eyebrow">A conversation is a good start</div><h1 class="detail-title">What’s on<br><span class="blue">your mind?</span></h1><form id="contact-form" class="form-grid" action="https://formsubmit.co/hello@muxion.in" method="POST" data-email-delivery="formsubmit"><input type="hidden" name="_subject" value="New MUXION website enquiry"><input type="hidden" name="_template" value="table"><div hidden><label>Leave this field empty<input name="_honey" tabindex="-1" autocomplete="off"></label></div><label>Your name<input name="name" required></label><label>Email<input name="email" type="email" required></label><label class="wide">I’m here for<select name="interest"><option>Learning design</option><option>A workshop</option><option>Personal mentorship</option><option>Build with MUXION</option><option>MUXION Learning</option></select></label><label class="wide">Tell us a little more<textarea name="message" required></textarea></label><div class="wide"><button class="btn" type="submit">Send enquiry ${icon('arrow')}</button><p class="form-note" style="margin-top:12px">Your enquiry is sent via FormSubmit to hello@muxion.in. <a href="/privacy" target="_blank" rel="noopener">How we use your information</a>. You may be asked to complete a spam check.</p></div></form></div><aside class="card pad"><h3>Prefer a direct hello?</h3><div class="stack" style="margin-top:32px"><a href="mailto:hello@muxion.in" class="row">${icon('mail','blue')} hello@muxion.in</a><a href="tel:+917708100469" class="row">${icon('phone','blue')} +91 77081 00469</a><a href="https://wa.me/917708100469" target="_blank" rel="noopener" class="btn secondary">Chat on WhatsApp ${icon('external')}</a></div></aside></div></div>`)}
function authPage(kind='login'){const admin=kind==='admin',signup=kind==='signup',forgot=kind==='forgot',reset=kind==='reset';return publicPage(`<div class="auth-layout"><div class="auth-brand"><div><div class="eyebrow">Your next chapter starts here</div><h1>Make room<br>for a little<br><span class="blue">possibility.</span></h1></div><div><blockquote>“${esc(testimonials[1].text)}”</blockquote><div class="quote-person"><img class="avatar" src="${testimonials[1].image}" alt="Manoj Kumar"><div>Manoj Kumar<small>UI/UX Designer</small></div></div></div></div><div class="auth-form">${badge(admin?'ADMIN ACCESS':'MUXION ACADEMY','blue')}<h2>${forgot?'Forgot your password?':reset?'A fresh start.':signup?'A little curiosity goes a long way.':admin?'Your studio awaits.':'Good to have you here.'}</h2><p class="muted" style="font-size:12px">${forgot?'We’ll help you find your way back.':reset?'Choose a new password for your account.':signup?'Create your account and make your next move.':admin?'Only authorised admins can enter the live portal.':'Pick up where your curiosity left off.'}</p>${!forgot&&!reset?`${btn('<b style="font-size:17px;color:#a4caff">G</b> Continue with Google','google-demo','secondary full','style="margin-top:28px"')}<div class="divider">OR WITH EMAIL</div>`:''}<form id="${forgot?'forgot-form':reset?'reset-form':signup?'signup-form':'login-form'}" data-admin="${admin}">${signup?'<label>Your name<input name="name" autocomplete="name" required></label>':''}${!reset?'<label>Email address<input type="email" name="email" required autocomplete="email" placeholder="you@example.com"></label>':''}${!forgot?`<label>${reset?'New password':'Password'}<input name="password" type="password" required minlength="8" autocomplete="${signup||reset?'new-password':'current-password'}" placeholder="At least 8 characters"></label>`:''}${signup?'<label style="display:flex;align-items:center;font-size:10px"><input type="checkbox" required> I agree to the <a href="/terms" target="_blank" rel="noopener">Terms of service</a> and acknowledge the <a href="/privacy" target="_blank" rel="noopener">Privacy policy</a>.</label>':''}${!forgot&&!reset&&!signup?link('/forgot-password','Forgot password?','text-link'):''}<button class="btn full" type="submit">${forgot?'Send reset email':reset?'Reset password':signup?'Create account':admin?'Sign in to the studio':'Sign in'} ${icon('arrow')}</button></form><p class="form-note" style="margin:20px 0">Sign in securely with Firebase. Purchases and course access are linked to your account across devices.</p><p class="muted" style="font-size:11px;margin-top:24px">${signup?`Already curious here? ${link('/login','Sign in','blue')}`:link('/signup','New to MUXION? Create an account','blue')}</p></div></div>`)}
