const learnerNav=[['/learner','My overview','grid'],['/learner/courses','My learning','book'],['/learner/wishlist','Wishlist','heart'],['/learner/workshops','Workshops','calendar'],['/learner/mentorship','Mentorship','users'],['/learner/momentum','Momentum','clock'],['/learner/certificates','Certificates','award'],['/learner/payments','Payments','wallet'],['/learner/profile','My profile','user'],['/learner/settings','Settings','settings']];
const adminNav=[['/admin','Overview','grid'],['/admin/courses','Courses','book'],['/admin/workshops','Workshops','calendar'],['/admin/mentorship','Mentorship','users'],['/admin/learners','Learners','user'],['/admin/orders','Orders & payments','wallet'],['/admin/certificates','Certificates','award'],['/admin/discussions','Discussions','message'],['/admin/media','Media library','image'],['/admin/content','Website content','file'],['/admin/enquiries','Enquiries','mail'],['/admin/settings','Settings','settings']];
function shell(content,isAdmin=false){const r=route(),nav=isAdmin?adminNav:learnerNav;return `<div class="shell"><aside class="sidebar">${logo()}<div class="side-label">${isAdmin?'YOUR TEACHING STUDIO':'YOUR LEARNING SPACE'}</div><nav aria-label="${isAdmin?'Admin':'Learner'} navigation">${nav.map(([p,t,i])=>link(p,`${icon(i)}<span>${t}</span>`,'side-link '+((r===p||(p!==(isAdmin?'/admin':'/learner')&&r.startsWith(p+'/')))?'active':''))).join('')}${isAdmin&&role==='super'?link('/admin/team',`${icon('shield')}<span>Admin team</span>`,'side-link '+(r==='/admin/team'?'active':'')):''}</nav><div class="sidebar-bottom"><div class="notice" style="padding:12px;font-size:9px">${isAdmin?'Your studio. Their next chapter.':'Little steps count. Keep going.'}</div>${link('/',`${icon('external')}<span>Visit website</span>`,'side-link')}${link('/page-map',`${icon('grid')}<span>All pages</span>`,'side-link')}${btn(`${icon('logout')} Sign out`,'logout','secondary small full')}</div></aside><div class="shell-main"><header class="shell-header"><span>${isAdmin?'MUXION / TEACHING STUDIO':'MUXION / YOUR NEXT CHAPTER'}</span><div class="row">${['super','admin'].includes(role)?link(isAdmin?'/learner':'/admin',isAdmin?'Learner':'Admin studio','btn secondary small'):''}<span class="muted">${role==='super'?'Owner':role==='admin'?'Admin':'Learner'}</span>${link(isAdmin?'/admin/notifications':'/learner/notifications',icon('bell'),'icon-btn')}<img class="avatar" src="${esc(db.profile.image)}" alt="Your profile"><div class="profile-name"><small>${esc(isAdmin?'Mariam Parvez':db.profile.name)}</small><p style="font-size:9px" class="${isAdmin?'admin-mode':'muted'}">${isAdmin?(role==='super'?'Super Admin':'Admin'):'A work in progress. In a good way.'}</p></div></div></header><div class="demo-bar">Signed in with Firebase · Purchases and access verified by the backend</div><main id="main" class="shell-content">${content}</main></div>${whatsapp()}</div>`}
function shellTitle(title,description,action=''){return `<div class="shell-title"><div><h1>${title}</h1><p>${description}</p></div>${action}</div>`}
function stats(items){return `<div class="grid4 stats">${items.map(([n,t,i,h])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><small>${t}</small><strong>${n}</strong>${h?`<div class="trend">${h}</div>`:''}</div>`).join('')}</div>`}
function chart(){const days=db.activity||[],max=Math.max(1,...days.map(d=>d.count));return `<div class="chart" aria-label="Lessons completed over the last seven days">${days.map(d=>`<div title="${esc(d.date)}: ${d.count} lessons"><i style="height:${Math.round(d.count/max*92)}px"></i><span>${esc(d.day)}</span></div>`).join('')}</div><p class="form-note" style="text-align:center;margin-top:12px">Completed lessons · last seven days</p>`}
function learnerOverview(){const c=db.courses.find(c=>db.enrolled.includes(c.id)),total=db.completed.length;return shell(`${shellTitle(`Hey ${esc(db.profile.name.split(' ')[0])}, keep your curiosity going. ✳`,'A small step today is a big part of your next chapter.',link('/courses',`Explore courses ${icon('arrow')}`,'btn secondary'))}${stats([[db.enrolled.length,'Enrolled courses','book','Lifetime access'],[total,'Lessons completed','check','Your progress, at your pace'],[db.certificates.length,'Certificates earned','award','Keep making progress'],[db.points,'Momentum points','spark','5 points unlock 2% off']])}<div class="dashboard-grid" style="margin-top:32px"><div class="stack"><div class="between"><h3>Pick up where you left off.</h3>${link('/learner/courses','My learning →','text-link')}</div>${c?`<article class="card continue-card">${art(c)}<div>${badge('YOUR NEXT CHAPTER','blue')}<h3>${esc(c.title)}</h3><p class="muted" style="font-size:11px;margin-bottom:20px">${esc(c.lessons.find(l=>!db.completed.includes(`${c.id}:${l.id}`))?.title||'You made it. Look at you!')}</p><div class="between" style="font-size:10px;margin-bottom:10px"><span class="muted">${done(c)} of ${c.lessons.length} lessons</span><span class="blue">${pct(c)}%</span></div><div class="progress"><i style="width:${pct(c)}%"></i></div><div style="margin-top:20px">${link('/learner/learn/'+c.id,`Let’s keep going ${icon('play')}`,'btn')}</div></div></article>`:empty('Your first chapter awaits.','Explore a course and start making things.','Find your course','/courses')}<div class="card pad"><div class="between"><h3>Your learning rhythm.</h3>${badge('THIS WEEK')}</div>${chart()}</div><div class="card pad"><div class="between"><div><div class="eyebrow">A little live inspiration</div><h3>Make room for the Design Lab.</h3><p class="muted" style="font-size:12px;margin-top:12px">Join Mariam for a focused, hands-on workshop.</p></div>${link('/workshops',icon('arrow'),'icon-btn')}</div></div></div><aside><div class="card pad"><div class="between"><h4>Find your focus.</h4>${icon('spark','blue')}</div><div class="momentum-circle" style="width:164px;height:164px;margin:28px auto"><strong style="font-size:32px">45:00</strong><small style="font-size:8px">MAKE A LITTLE SPACE</small></div><p class="muted" style="font-size:11px;text-align:center;margin-bottom:20px">One focused session. One step forward.</p>${link('/learner/momentum','Start a focus session','btn full')}</div><div class="card pad" style="margin-top:24px"><h4>A nudge from your mentor.</h4><p class="quote" style="font-size:12px">“You don’t need to know everything to begin. You just need to begin.”</p><div class="row"><img class="avatar" src="${portraits.mariam}" alt="Mariam"><small>Mariam · Your mentor</small></div></div></aside></div>`)}
function learnerCourses(wishlist=false){let items=db.courses.filter(c=>(wishlist?db.wishlist:db.enrolled).includes(c.id));if(!wishlist){if(tab==='progress')items=items.filter(c=>pct(c)<100);if(tab==='completed')items=items.filter(c=>pct(c)===100)}return shell(`${shellTitle(wishlist?'For your “one day” list.':'Your learning, your pace.',wishlist?'Save a little possibility for later.':'Every chapter brings you closer to the things you want to create.',link('/courses','Explore courses →','btn secondary'))}${!wishlist?`<div class="tabs">${[['all','All courses'],['progress','In progress'],['completed','Completed']].map(([v,t])=>btn(t,'learner-tab','tab '+(tab===v?'active':''),`data-value="${v}"`)).join('')}</div>`:''}${items.length?`<div class="grid3">${items.map(c=>courseCard(c,wishlist?'public':'learner')).join('')}</div>`:empty(wishlist?'Make a little wishlist.':'A new chapter is waiting.',wishlist?'Tap the heart on a course that catches your eye.':'No courses in this view yet. Keep learning or explore something new.','Explore courses','/courses',wishlist?'heart':'book')}`)}
function learnerPlayer(id){if(db.enrolled.includes(id)&&!loadedCourses.has(id)){if(courseErrors.has(id))return shell(empty('Could not open this course.',courseErrors.get(id),'Back to my courses','/learner/courses'));loadCourse(id);return shell(empty('Opening your course.','Checking your purchase and loading protected lessons.','','','book'));}const c=cBy(id);if(!c||!db.enrolled.includes(id))return shell(empty('This course is waiting for you.','Explore the course page to see what’s inside.','Explore courses','/courses'));let l=c.lessons.find(l=>l.id===lessonId)||c.lessons[0];if(!l)return shell(empty('Lessons are being prepared.','Your tutor has not added lessons to this course yet.','Back to my learning','/learner/courses'));lessonId=l.id;const complete=db.completed.includes(`${id}:${l.id}`);let stage;if(l.type==='video'){let url=l.url;if(url&&/youtu(?:be\.com|\.be)/.test(url)){let vid;try{const u=new URL(url);vid=u.hostname==='youtu.be'?u.pathname.slice(1):u.searchParams.get('v')||u.pathname.split('/').pop()}catch{}stage=vid&&/^[a-zA-Z0-9_-]+$/.test(vid)?`<iframe title="${esc(l.title)}" src="https://www.youtube-nocookie.com/embed/${vid}" allowfullscreen></iframe>`:''}else if(url&&(url.startsWith('blob:')||url.startsWith('data:video/')||/^https:\/\//.test(url)))stage=`<video controls src="${esc(url)}" aria-label="${esc(l.title)}"></video>`;if(!stage)stage=`<div>${icon('play','blue')}<h3 style="margin-top:20px">Your next lesson lives here.</h3><p>The original video isn’t embedded in the Make archive. Your tutor can add a video in the course editor. You can still explore the complete learning interface.</p>${badge('VIDEO NOT YET AVAILABLE')}</div>`}else if(l.type==='quiz'){stage=`<div>${icon('spark','blue')}<h3 style="margin-top:16px">A little checkpoint.</h3><p>Put your design thinking into practice.</p>${btn('Take the quiz','take-quiz','',`data-id="${id}"`)}</div>`}else stage=`<div>${icon('file','blue')}<h3 style="margin:16px 0">${esc(l.title)}</h3><p>${esc(l.body||'Your tutor can add study materials or an assignment brief in the course editor.')}</p>${l.url?`<a class="btn secondary" href="${safeUrl(l.url)}" target="_blank" rel="noopener">Open resource ${icon('external')}</a>`:''}${l.type==='assignment'?`<form id="assignment-form" data-id="${id}" data-lesson="${l.id}" class="stack"><label>Project or prototype URL<input name="url" type="url" required placeholder="https://www.figma.com/…"></label><button class="btn small" type="submit">Submit project</button></form>`:''}</div>`;
return shell(`${shellTitle(esc(c.title),'Make a little progress. It all adds up.',link('/learner/courses','Back to my learning','btn secondary'))}<div class="learning-layout"><div><div class="video-stage">${stage}</div><div class="between" style="margin:24px 0"><div><small class="blue">CHAPTER / ${esc(l.section)}</small><h3 style="margin-top:8px">${esc(l.title)}</h3></div>${btn(complete?`${icon('check')} Completed`:'Mark complete','complete-lesson',complete?'secondary':'',`data-id="${id}" data-lesson="${l.id}" ${complete?'disabled':''}`)}</div><div class="tabs">${[['overview','Overview'],['notes','My notes'],['discussion','Discussion'],['resources','Resources']].map(([t,n])=>btn(n,'player-tab','tab '+(playerTab===t?'active':''),`data-value="${t}"`)).join('')}</div>${playerContent(c,l)}<div class="between" style="margin-top:32px">${btn('← Previous lesson','prev-lesson','secondary',`data-id="${id}"`)}${btn(`Next lesson ${icon('arrow')}`,'next-lesson','',`data-id="${id}"`)}</div></div><aside class="card"><div class="pad"><div class="between"><h4>Your course</h4><span class="blue" style="font-size:11px">${pct(c)}%</span></div><div class="progress" style="margin:16px 0"><i style="width:${pct(c)}%"></i></div><small class="muted">${done(c)} of ${c.lessons.length} lessons complete</small></div>${c.lessons.map((x,i)=>`<button class="player-lesson ${x.id===l.id?'active':''} ${db.completed.includes(`${id}:${x.id}`)?'done':''}" data-action="select-lesson" data-id="${x.id}">${icon(db.completed.includes(`${id}:${x.id}`)?'check':x.type==='video'?'play':'file')}<span class="grow">${String(i+1).padStart(2,'0')}. ${esc(x.title)}</span><small>${x.minutes}m</small></button>`).join('')}<div class="pad"><p class="form-note">All lessons, resources, quizzes and assignments count toward your completion certificate.</p></div></aside></div>`)}
function playerContent(c,l){if(playerTab==='notes')return `<form id="notes-form" data-id="${c.id}:${l.id}" class="stack"><label>Your notes. Just for you.<textarea name="notes" rows="6" placeholder="An idea, a question, a little aha moment…">${esc(db.notes[`${c.id}:${l.id}`]||'')}</textarea></label><div>${btn('Save my notes','save-notes')}</div><p class="form-note">Private notes are saved securely to your account.</p></form>`;if(playerTab==='discussion')return `<div class="stack">${db.comments.filter(post=>post.courseId===c.id).map(c=>`<div class="card pad"><strong style="font-size:12px">${esc(c.name)}</strong><p style="font-size:12px;margin-top:12px">${esc(c.text)}</p><small class="muted">${esc(c.date)}</small><div>${btn('Reply','reply-comment','secondary small',`data-id="${c.id}"`)}</div></div>`).join('')}<form id="comment-form" class="stack"><label>Join the conversation<textarea name="text" required placeholder="Ask a question or share an idea…"></textarea></label><button class="btn" type="submit">Post comment ${icon('message')}</button><p class="form-note">Visible to enrolled learners and tutors in this course.</p></form></div>`;if(playerTab==='resources')return `<div class="stack">${c.lessons.filter(l=>l.type==='resource').map(l=>`<div class="card pad"><h4>${esc(l.title)}</h4><p class="muted" style="font-size:12px;margin:12px 0">${esc(l.body)}</p>${l.url?`<a class="text-link" href="${safeUrl(l.url)}" target="_blank" rel="noopener">Open material ${icon('external')}</a>`:badge('Tutor material / text resource')}</div>`).join('')||'<p class="muted">Your tutor hasn’t added resources yet.</p>'}</div>`;return `<div class="card pad"><h4>A little context.</h4><p class="muted" style="font-size:12px;margin-top:16px">${esc(c.description)}</p><div class="divider"></div><div class="row"><img class="avatar" src="${portraits.mariam}" alt="Your tutor"><div><strong style="font-size:12px">${esc(c.tutor)}</strong><p class="muted" style="font-size:10px">Your guide from basics to brilliance.</p></div></div></div>`}
let timer={phase:'focus',remaining:2700,running:false,end:0,focusDone:false},timerTick;
function momentum(){return shell(`${shellTitle('Meet your Momentum.','Make space for focus. Make time to reset. Let the little wins add up.') }<div class="dashboard-grid"><div class="card pad timer-panel"><div class="eyebrow" style="justify-content:center">YOUR LITTLE LEARNING RITUAL</div><h2>One thing at a time.</h2><p class="muted" style="font-size:12px;margin-top:12px">${timer.phase==='focus'?'45 minutes to give your curiosity your attention.':'15 minutes to stretch, step away and reset.'}</p><div class="momentum-circle"><strong id="timer-value">${timerText()}</strong><small id="timer-phase">${timer.phase==='focus'?'FOCUS TIME':'TAKE A BREATH'}</small></div><div class="row">${btn(`${icon(timer.running?'pause':'play')} ${timer.running?'Pause':'Start '+(timer.phase==='focus'?'focus':'break')}`,'timer-toggle','',`id="timer-button"`)}${btn('Reset','timer-reset','secondary')}</div><p class="form-note" style="margin:24px 0">Complete 45 minutes of focus and the full 15-minute break to earn 1 point. Focus pauses when this tab is hidden. This frontend timer cannot verify attention.</p><div class="divider"></div><div class="between"><div><strong style="font-size:24px">${db.sessions.length}</strong><p class="muted" style="font-size:10px">Completed cycles</p></div><div><strong style="font-size:24px">${db.points}</strong><p class="muted" style="font-size:10px">Available points</p></div><div><strong style="font-size:24px">${rewardPercent()}%</strong><p class="muted" style="font-size:10px">Current reward</p></div></div></div><aside><div class="card"><div class="pad"><h3>Little wins. Real rewards.</h3><p class="muted" style="font-size:11px;margin-top:12px">Earn up to 5% off your next self-paced course. Points are spent when you apply a reward.</p></div>${[[5,2],[10,3],[20,5]].map(([p,d])=>`<div class="reward-step"><span>${d}%</span><div><strong>${p} points</strong><p>One next-course purchase</p></div>${db.points>=p?icon('check','green'):''}</div>`).join('')}<div class="pad"><p class="form-note">Available to enrolled learners. No cash value. One reward per course purchase. Demonstration rules, pending your final approval.</p></div></div></aside></div>`)}
function timerText(){return `${String(Math.floor(timer.remaining/60)).padStart(2,'0')}:${String(timer.remaining%60).padStart(2,'0')}`}
function rewardPercent(){return db.points>=20?5:db.points>=10?3:db.points>=5?2:0}
function tick(){if(!timer.running)return;timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));if($('#timer-value'))$('#timer-value').textContent=timerText();if(timer.remaining===0){timer.running=false;if(timer.phase==='focus'){timer.focusDone=true;timer.phase='break';timer.remaining=900;toast('Good focus. Take your full 15-minute break next.')}else{if(timer.focusDone){db.points++;db.sessions.push({date:new Date().toISOString(),minutes:60});save();toast('One complete cycle. One Momentum point. Nicely done.')}timer={phase:'focus',remaining:2700,running:false,end:0,focusDone:false}}if(route()==='/learner/momentum')render()}}
function learnerEvents(type){const isWorkshop=type==='workshops',items=db.bookings.filter(b=>b.type===(isWorkshop?'workshop':'mentorship'));return shell(`${shellTitle(isWorkshop?'Your live learning.':'Your personal next steps.',isWorkshop?'The sessions, people and ideas you’re making time for.':'A little guidance goes a long way.',link(isWorkshop?'/workshops':'/mentorship',isWorkshop?'Explore workshops →':'Find a session →','btn secondary'))}${items.length?`<div class="grid2">${items.map(b=>{const w=isWorkshop?wBy(b.offerId):null;return `<article class="card pad">${badge(isWorkshop?'PAID · CONFIRMED':b.status,'green')}<h3 style="margin:20px 0">${esc(b.title)}</h3><p class="muted" style="font-size:12px">${esc(b.date)} · ${esc(b.time||'')} ${esc(b.timezone||'Asia/Kolkata')}</p><div class="divider"></div>${isWorkshop?`${w?.meet?`<a class="btn full" href="${safeUrl(w.meet)}" target="_blank" rel="noopener">Open Google Meet ${icon('external')}</a>`:'<p class="notice">Your tutor hasn’t added the Meet link yet.</p>'}<div style="margin-top:12px">${w?.whatsapp?`<a class="btn secondary full" href="${safeUrl(w.whatsapp)}" target="_blank" rel="noopener">Join WhatsApp group ${icon('external')}</a>`:'<p class="form-note">The private WhatsApp invitation will appear here when added by your tutor.</p>'}</div>`:`<p class="muted" style="font-size:12px">Your request: ${esc(b.goals||'Personal design guidance')}</p>${b.meet&&b.status==='Confirmed'?`<a class="btn" href="${safeUrl(b.meet)}" target="_blank" rel="noopener">Join your session</a>`:''}<div style="margin-top:20px">${btn('Request a reschedule','reschedule','secondary small',`data-id="${b.id}"`)}</div>`}</article>`}).join('')}</div>`:empty(isWorkshop?'Your next live moment is waiting.':'A conversation can change a lot.',isWorkshop?'Join a workshop and your session details will live here.':'Book a personal session and manage your requests here.',isWorkshop?'Explore workshops':'Explore mentorship',isWorkshop?'/workshops':'/mentorship','calendar')}`)}
function certMarkup(cert){return `<div class="certificate"><div class="brand">MUXION</div><div class="cert-title">CERTIFICATE OF COMPLETION</div><p>This celebrates the curiosity and commitment of</p><h2>${esc(cert.name)}</h2><p>who has completed all required elements of</p><strong>${esc(cert.course)}</strong><span class="seal">✳</span><div class="cert-bottom"><span>Mariam Parvez / Founder & Mentor</span><span>${esc(cert.date)} · ${esc(cert.id)}</span></div></div>`}
function certificates(admin=false){return shell(`${shellTitle(admin?'Certificates & proud moments.':'Look what you made possible.',admin?'Completion records and public verification.':'Your effort, made official. Download it. Share it. Be proud.')}${db.certificates.length?`<div class="grid2">${db.certificates.map(cert=>`<article class="card">${certMarkup(cert)}<div class="pad"><div class="between"><span class="muted" style="font-size:10px">${esc(cert.id)}</span>${link('/verify/'+cert.id,'Verify ↗','text-link')}</div><div class="row wrap" style="margin-top:16px">${admin&&cert.status==='Valid'?btn('Revoke certificate','revoke-cert','danger small',`data-id="${cert.id}"`):''}${badge(cert.status||'Valid',cert.status==='Revoked'?'red':'green')}${['png','jpg','pdf'].map(t=>btn(`${icon('download')} ${t.toUpperCase()}`,'download-cert','secondary small',`data-id="${cert.id}" data-format="${t}"`)).join('')}</div></div></article>`).join('')}</div>`:empty('Your next proud moment is ahead.','Complete every required lesson, resource, quiz and assignment in a course to unlock a unique certificate.','Keep learning','/learner/courses','award')}`,admin)}
function verify(id=''){if(id&&!verificationCache.has(id)&&!verificationLoading.has(id)){verificationLoading.add(id);platformRequest('certificate-verify',{query:{id}}).then(data=>verificationCache.set(id,data)).catch(error=>verificationCache.set(id,{error:error.message})).finally(()=>{verificationLoading.delete(id);if(route()==='/verify/'+id)render();});}const data=verificationCache.get(id),cert=data?.certificate;return publicPage(`<div class="container section" style="max-width:900px"><div class="eyebrow">VERIFIED BY MUXION</div><h1 class="detail-title">Verify a certificate.</h1><form id="verify-form" class="row" style="margin:32px 0"><label>Certificate ID<input name="id" required value="${esc(id)}"></label><button class="btn" type="submit">Verify</button></form>${id?data?.error?`<p class="notice">${esc(data.error)}</p>`:!data?'<p>Checking the certificate…</p>':cert?`<p class="notice">${esc(cert.status)} certificate · verified against the MUXION register</p>${certMarkup(cert)}`:'<p class="notice">No certificate found. Check the ID and try again.</p>':''}<p class="form-note">Verification shows the certificate holder’s name, course, date and current validity. Email and private learning records are never published.</p></div>`);}
function payments(){return shell(`${shellTitle('Everything, accounted for.','Your account purchases and receipts, available across devices.') }<div class="tabs">${[['all','Payment history'],['cards','Saved payment methods']].map(([v,n])=>btn(n,'payment-tab','tab '+(tab===v?'active':''),`data-value="${v}"`)).join('')}</div>${paymentHistoryCursor?btn('Load more purchases','more-payments','secondary small'):''}${tab==='cards'?`<div class="notice" style="margin-bottom:24px">Card saving will be managed securely by your payment provider. No card number or CVV is stored by this frontend.</div>${empty('Your payment methods will live here.','Choose a payment method securely in Razorpay Checkout. MUXION does not store your card details.','','','wallet')}`:`<div class="table-wrap"><table><thead><tr><th>Purchase</th><th>Date & time</th><th>Amount</th><th>Status</th><th>Receipt</th></tr></thead><tbody>${db.transactions.map(t=>`<tr><td><strong>${esc(t.title)}</strong><small>${esc(t.id)}</small></td><td>${new Date(t.date).toLocaleString('en-IN',{timeZone:db.profile.timezone||'Asia/Kolkata'})}<small>${esc(db.profile.timezone)}</small></td><td>${money(t.amount)}</td><td>${badge(t.status,'green')}</td><td>${btn(icon('download'),'receipt','secondary small',`data-id="${t.id}" aria-label="Download payment acknowledgement"`)}</td></tr>`).join('')}</tbody></table></div>`}`)}
function profile(){return shell(`${shellTitle('A little more you.','Your profile, contact details and the way you show up.') }<form id="profile-form" class="editor-layout"><div class="editor-section"><h3>Your personal details</h3><div class="form-grid"><label>Full name<input name="name" required value="${esc(db.profile.name)}"></label><label>Email address<input name="email" type="email" required value="${esc(db.profile.email)}"></label><label>Phone number<input name="phone" type="tel" value="${esc(db.profile.phone)}"></label><label>Timezone<select name="timezone">${['Asia/Kolkata','Europe/London','America/New_York','Asia/Dubai','Australia/Sydney','UTC'].map(t=>`<option ${db.profile.timezone===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="wide">A little about you<textarea name="bio">${esc(db.profile.bio)}</textarea></label></div><p class="form-note" style="margin-top:24px">Your sign-in email is verified by Firebase and cannot be changed here.</p><div class="form-actions"><button class="btn" type="submit">Save my profile ${icon('check')}</button></div></div><aside class="card pad"><img class="avatar large" id="profile-preview" src="${esc(db.profile.image)}" alt="Profile photo"><h3 style="margin:24px 0 12px">A face to your name.</h3><p class="form-note">Your Google profile photo is used for your account.</p><p class="form-note" style="margin-top:12px">PNG, JPG or WebP. Up to 2MB for this browser demo.</p></aside></form>`)}
function settings(admin=false){return shell(`${shellTitle(admin?'The studio settings.':'Make yourself at home.',admin?'Your brand details and integration readiness.':'A few preferences for the way you learn.')}${admin?`<form id="site-settings-form" class="card pad"><h3 style="margin-bottom:24px">Brand & contact</h3><div class="form-grid"><label>Site name<input name="siteName" required value="${esc(db.settings.siteName)}"></label><label>Contact email<input name="email" type="email" required value="${esc(db.settings.email)}"></label><label>WhatsApp phone<input name="phone" required value="${esc(db.settings.phone)}"></label><label>Default currency<select name="currency"><option>INR</option></select></label></div><div class="form-actions"><button class="btn" type="submit">Save settings</button></div></form><div class="card pad" style="margin-top:24px"><h3>Ready for the next chapter.</h3>${[['Firebase','Not configured · phase two'],['Google & email sign-in','Frontend only'],['Payment gateway','Not selected · international support required'],['Phone OTP','Planned for v2']].map(([t,p])=>`<div class="settings-row"><div><h4>${t}</h4><p>${p}</p></div>${badge('NOT CONNECTED')}</div>`).join('')}</div>`:`<div class="card pad"><h3>Learning preferences</h3><form id="preferences-form">${[['reminders','A little nudge to learn','Email reminders about your learning goals'],['workshops','Workshop updates','New sessions and booking reminders'],['community','Community conversations','Replies to your questions and comments']].map(([n,t,p])=>`<label class="settings-row"><span><h4>${t}</h4><p>${p}</p></span><input type="checkbox" name="${n}" ${db.preferences?.[n]===false?'':'checked'}></label>`).join('')}<div class="form-actions"><button class="btn" type="submit">Save preferences</button></div></form></div><div class="card pad" style="margin-top:24px"><h3>Account & security</h3><div class="settings-row"><div><h4>Password</h4><p>Keep your account secure.</p></div>${btn('Change password','change-password','secondary small')}</div><div class="settings-row"><div><h4>Connected accounts</h4><p>Google sign-in will be available after Firebase setup.</p></div>${badge('NOT CONNECTED')}</div><div class="settings-row"><div><h4>Your data</h4><p>Download your local preview records.</p></div>${btn('Export demo data','export-data','secondary small')}</div><div class="settings-row"><div><h4>Reset this demo</h4><p>Restores the seeded frontend content in this browser.</p></div>${btn('Reset demo','reset-demo','danger small')}</div></div>`}`,admin)}
function notifications(admin=false){return shell(`${shellTitle('A little heads-up.','The things that keep your next chapter moving.') }<div class="card">${[['spark','Welcome to your MUXION account.','Your private notes and course progress are linked to your account.'],['book','UI/UX Design Mastery is ready to explore.','Your course workspace includes lessons, resources, notes, a quiz and a project.'],['shield','Your account is protected.','Sign-in, enrolment and certificate validity are checked by the backend.']].map(([i,t,p])=>`<div class="notification">${icon(i)}<div><h4>${t}</h4><p class="muted" style="margin:8px 0">${p}</p><small>Account guide</small></div></div>`).join('')}</div>`,admin)}
function adminOverview(){return shell(`${shellTitle('Good things start in your studio.','Create the experiences that help your learners move forward.',link('/admin/courses/new',`${icon('plus')} Create a course`,'btn'))}<div class="banner between"><div><div class="eyebrow" style="margin-bottom:10px">YOUR STUDIO, AT A GLANCE</div><h3>A little preparation. A lot of possibility.</h3><p>Publish your courses and set prices here. Learners see the same saved catalogue at checkout.</p></div>${icon('spark','blue')}</div>${stats([[db.courses.length,'Self-paced courses','book',`${db.courses.filter(c=>c.status==='Published').length} published`],[db.users.filter(u=>u.role==='Learner').length,'Learners','users','Registered accounts'],[db.workshops.length,'Live workshops','calendar','Make something together'],[money(db.transactions.reduce((s,t)=>s+t.amount,0)),'Recorded order value','wallet','Verified payment records']])}<div class="dashboard-grid" style="margin-top:32px"><div class="stack"><div class="card pad"><div class="between"><h3>Your studio activity.</h3>${badge('ILLUSTRATIVE')}</div>${chart()}</div><div><div class="between" style="margin-bottom:24px"><h3>Your latest courses.</h3>${link('/admin/courses','Manage all →','text-link')}</div>${courseTable(db.courses.slice(0,4))}</div><div class="card pad"><h3>Make the next thing happen.</h3><div class="grid3" style="margin-top:24px">${[['/admin/courses/new','A new course','book'],['/admin/workshops/new','A live workshop','calendar'],['/admin/mentorship/new','A mentorship offer','users']].map(([p,t,i])=>link(p,`${icon(i,'blue')}<p style="margin-top:12px;font-size:12px">${t} ↗</p>`,'card pad')).join('')}</div></div></div><aside><div class="card pad"><div class="eyebrow">NEXT LIVE SESSION</div><h3>${esc(db.workshops[0]?.title||'Your next workshop')}</h3><p class="muted" style="font-size:11px;margin:16px 0 24px">${db.workshops[0]?formatWorkshop(db.workshops[0]):'Create a live session to bring people together.'}</p>${link(db.workshops[0]?'/admin/workshops/'+db.workshops[0].id:'/admin/workshops/new','Prepare your workshop →','btn secondary full')}</div><div class="card pad" style="margin-top:24px"><h4>Before you launch.</h4><div style="margin-top:24px">${list(['Review all frontend journeys','Add your original course videos','Confirm prices & workshop dates','Connect Firebase & payments'])}</div></div></aside></div>`,true)}
function courseTable(items){return `<div class="table-wrap"><table><thead><tr><th>Course</th><th>Status</th><th>Content</th><th>Price</th><th>Actions</th></tr></thead><tbody>${items.map(c=>`<tr><td><strong>${esc(c.title)}</strong><small>${esc(c.category)}</small></td><td>${badge(c.status,c.status==='Published'?'green':'yellow')}</td><td>${c.lessons.length} lessons</td><td>${money(c.price)}</td><td><div class="row">${link('/admin/courses/'+c.id,icon('edit'),'icon-btn')}${link('/course/'+c.id,icon('external'),'icon-btn')}${btn(icon('trash'),'delete-course','danger small',`data-id="${c.id}" aria-label="Delete ${esc(c.title)}"`)}</div></td></tr>`).join('')||'<tr><td colspan="5">No courses yet. Create your first course.</td></tr>'}</tbody></table></div>`}
function adminCourses(){const items=db.courses.filter(c=>c.title.toLowerCase().includes(courseSearch.toLowerCase())&&(tab==='all'||c.status.toLowerCase()===tab));return shell(`${shellTitle('Your courses. Their next chapter.','Curate, publish and keep your learning experiences growing.',link('/admin/courses/new',`${icon('plus')} Create course`,'btn'))}<div class="toolbar"><input id="admin-course-search" type="search" value="${esc(courseSearch)}" placeholder="Search your courses…" aria-label="Search admin courses"><select id="admin-status-filter" aria-label="Filter by status"><option value="all">All statuses</option><option value="published" ${tab==='published'?'selected':''}>Published</option><option value="draft" ${tab==='draft'?'selected':''}>Draft</option></select></div>${courseTable(items)}`,true)}
function input(label,name,value,type='text',required=false,extra=''){return `<label>${label}<input type="${type}" name="${name}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`}
function area(label,name,value,extra=''){return `<label ${extra}>${label}<textarea name="${name}">${esc(value)}</textarea></label>`}
function select(label,name,value,options){return `<label>${label}<select name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`}
let draftCourse=null,draftWorkshop=null;
function courseEditor(id){if(!draftCourse||draftCourse._key!==id){const original=cBy(id);draftCourse=original?clone(original):{id:'c'+crypto.randomUUID().slice(0,8),title:'',subtitle:'',category:'UI / UX design',price:299,original:999,status:'Draft',level:'All levels',language:'English',tutor:'Mariam Parvez',description:'',outcomes:[],requirements:'',audience:'',image:'',lessons:[],quiz:{question:'',options:['','',''],answer:0}};draftCourse._key=id}const c=draftCourse;return shell(`${shellTitle(id==='new'?'Make room for a new course.':'Shape your next learning experience.','Everything you curate here shapes the public course page.',`<div class="row">${link('/admin/courses','Back','btn secondary')}${btn('Save course','save-course','',`data-id="${c.id}"`)}</div>`)}<form id="course-form" data-id="${c.id}"><div class="editor-layout"><div><section class="editor-section"><h3>01 / The first impression</h3><div class="form-grid">${input('Course title','title',c.title,'text',true)}${input('Short headline','subtitle',c.subtitle)}${area('Course description','description',c.description,'class="wide"')}${select('Discipline','category',c.category,topics.slice(1))}${select('Level','level',c.level,['All levels','Beginner','Intermediate','Advanced'])}${input('Language','language',c.language)}${input('Tutor name','tutor',c.tutor)}</div></section><section class="editor-section"><h3>02 / The promise</h3><div class="stack">${area('What learners will be able to do · one pointer per line','outcomes',c.outcomes.join('\n'))}${area('Who is this course for?','audience',c.audience)}${area('Requirements & prerequisites','requirements',c.requirements)}</div></section><section class="editor-section"><div class="between"><h3 style="margin:0">03 / The learning journey</h3>${btn(`${icon('plus')} Add content`,'add-lesson','secondary small')}</div><p class="form-note" style="margin:16px 0">Drag to reorder. Arrow controls work with keyboard and touch. Add videos, study resources, quizzes and assignments in any order.</p><div id="curriculum-items">${c.lessons.map((l,i)=>`<div class="curriculum-item" draggable="true" data-index="${i}">${icon('grip','muted')}<div class="grow"><strong>${esc(l.title)}</strong><small>${esc(l.section)} · ${l.type} · ${l.minutes} min ${l.type==='video'&&!l.url?'· Video missing':''}</small></div><button type="button" data-action="move-lesson" data-index="${i}" data-direction="-1" aria-label="Move lesson up" ${i===0?'disabled':''}>↑</button><button type="button" data-action="move-lesson" data-index="${i}" data-direction="1" aria-label="Move lesson down" ${i===c.lessons.length-1?'disabled':''}>↓</button><button type="button" data-action="edit-lesson" data-index="${i}" aria-label="Edit lesson">${icon('edit')}</button><button type="button" data-action="remove-lesson" data-index="${i}" aria-label="Delete lesson">${icon('trash')}</button></div>`).join('')||'<div class="notice">Your first lesson starts here. Add a video, resource, quiz or project.</div>'}</div></section><section class="editor-section"><h3>04 / The checkpoint quiz</h3><div class="stack">${input('Question','quizQuestion',c.quiz.question)}${c.quiz.options.map((o,i)=>input('Answer option '+(i+1),'option'+i,o)).join('')}${select('Correct option','quizAnswer',String(c.quiz.answer+1),['1','2','3'])}<p class="form-note">The quiz lesson uses this question. Learners must answer correctly to complete that lesson.</p></div></section></div><aside><div class="editor-section"><h3>Publish & price</h3><div class="stack">${select('Visibility','status',c.status,['Draft','Published'])}${input('Course price · INR','price',c.price,'number',true,'min="0" step="1"')}${input('Original price · INR','original',c.original,'number',false,'min="0" step="1"')}<div class="notice">Self-paced access is lifetime. Certificates require completion of all course elements.</div><button type="submit" class="btn full">Save course ${icon('check')}</button></div></div><div class="editor-section"><h3>Course cover</h3>${art(c)}<div style="margin-top:20px"><label>Upload a cover<input type="file" id="course-cover" accept="image/*"></label></div><p class="form-note" style="margin-top:12px">For this preview, images up to 2MB are stored in your browser.</p></div><div class="notice">Original content recovery is partial. Draft lessons demonstrate the complete frontend; add the real video files before publishing live.</div></aside></div></form>`,true)}
function workshopList(){return shell(`${shellTitle('Your live learning moments.','Curate a workshop, fill the room and make something happen.',link('/admin/workshops/new',`${icon('plus')} Create workshop`,'btn'))}<div class="grid2">${db.workshops.map(w=>`<article class="card">${art(w,'live')}<div class="pad"><div class="between">${badge(w.status,w.status==='Published'?'green':'yellow')}<div class="row">${link('/admin/workshops/'+w.id,icon('edit'),'icon-btn')}${btn(icon('trash'),'delete-workshop','danger small',`data-id="${w.id}" aria-label="Delete workshop"`)}</div></div><h3 style="margin:20px 0 12px">${esc(w.title)}</h3><p class="muted" style="font-size:11px">${formatWorkshop(w)}</p><div class="between" style="margin-top:24px"><span class="price">${money(w.price)}</span>${btn(`${icon('image')} Instagram creative`,'poster','secondary small',`data-id="${w.id}"`)}</div></div></article>`).join('')||empty('Your next live session starts here.','Create a workshop with all the details your learners need.','Create workshop','/admin/workshops/new','calendar')}</div>`,true)}
function workshopEditor(id){if(!draftWorkshop||draftWorkshop._key!==id){draftWorkshop=wBy(id)?clone(wBy(id)):{id:'w'+crypto.randomUUID().slice(0,8),title:'',topic:'',date:'',time:'17:00',timezone:'Asia/Kolkata',duration:120,price:499,original:999,status:'Draft',capacity:30,tutor:'Mariam Parvez',bio:'',photo:portraits.mariam,meet:'',whatsapp:'',payment:'',pointers:[],recording:false};draftWorkshop._key=id}const w=draftWorkshop;return shell(`${shellTitle(id==='new'?'Bring a new workshop to life.':'Shape a live learning moment.','Your workshop details become its public invite page.',link('/admin/workshops','Back to workshops','btn secondary'))}<form id="workshop-form" data-id="${w.id}" class="editor-layout"><div><section class="editor-section"><h3>01 / The invitation</h3><div class="form-grid">${input('Workshop / course name','title',w.title,'text',true)}${input('Topic or headline','topic',w.topic,'text',true)}${area('What will be covered · one pointer per line','pointers',w.pointers.join('\n'),'class="wide"')}${input('Date','date',w.date,'date',true)}${input('Start time','time',w.time,'time',true)}${select('Timezone','timezone',w.timezone,['Asia/Kolkata','Europe/London','America/New_York','Asia/Dubai','UTC'])}${input('Duration · minutes','duration',w.duration,'number',true,'min="15"')}${input('Capacity · seats','capacity',w.capacity,'number',true,'min="1"')}<label style="display:flex;align-items:center;gap:12px"><input name="recording" type="checkbox" ${w.recording?'checked':''}> Recording included</label></div></section><section class="editor-section"><h3>02 / The person leading it</h3><div class="stack">${input('Tutor name','tutor',w.tutor,'text',true)}${area('About the tutor','bio',w.bio)}<div class="row"><img class="avatar large" src="${esc(w.photo)}" alt="Tutor"><label style="flex:1">Tutor photo<input type="file" id="workshop-photo" accept="image/*"></label></div></div></section><section class="editor-section"><h3>03 / The connections</h3><div class="stack">${input('Google Meet link · private after payment','meet',w.meet,'url')}${input('WhatsApp group invite · private after payment','whatsapp',w.whatsapp,'url')}${input('Payment link · future gateway integration','payment',w.payment,'url')}<p class="form-note">Meet and WhatsApp details appear only in the paid state in this demo. Production requires server-verified payments and protected records; hiding links in frontend code is not access control.</p></div></section></div><aside><section class="editor-section"><h3>Make it official.</h3><div class="stack">${select('Visibility','status',w.status,['Draft','Published'])}${input('Original price · INR','original',w.original,'number',true,'min="0"')}${input('Discounted price · INR','price',w.price,'number',true,'min="0"')}<button type="submit" class="btn full">Save workshop ${icon('check')}</button>${id!=='new'?btn('Generate Instagram PNG','poster','secondary full',`data-id="${w.id}"`):''}</div></section><div class="notice">Workshop dates and prices are seeded demo content. Review them before launch.</div></aside></form>`,true)}
function mentorshipAdmin(id){if(id){const m=db.mentorships.find(m=>m.id===id)||{id:'m'+crypto.randomUUID().slice(0,8),title:'',price:2499,duration:60,status:'Draft',tutor:'Mariam Parvez',description:'',pointers:[]};return shell(`${shellTitle('A personal offer, thoughtfully made.','Create a single session or an offer learners can discuss with you.',link('/admin/mentorship','Back','btn secondary'))}<form id="mentorship-form" data-id="${m.id}" class="card pad"><div class="form-grid">${input('Offer title','title',m.title,'text',true)}${input('Tutor','tutor',m.tutor,'text',true)}${area('Description','description',m.description,'class="wide"')}${area('Included in this offer · one per line','pointers',m.pointers.join('\n'),'class="wide"')}${input('Session price · INR','price',m.price,'number',true,'min="0"')}${input('Duration · minutes','duration',m.duration,'number',true,'min="15"')}${select('Visibility','status',m.status,['Draft','Published'])}</div><div class="form-actions"><button class="btn" type="submit">Save mentorship offer</button></div></form>`,true)}return shell(`${shellTitle('Personal guidance. Thoughtfully managed.','Your offers, bookings and conversations.',link('/admin/mentorship/new',`${icon('plus')} Create offer`,'btn'))}<div class="grid2">${db.mentorships.map(m=>`<article class="card pad">${badge(m.status,m.status==='Published'?'green':'yellow')}<h3 style="margin:20px 0">${esc(m.title)}</h3><p class="muted" style="font-size:12px">${esc(m.description)}</p><div class="between" style="margin-top:24px"><span class="price">${money(m.price)}</span><div class="row">${link('/admin/mentorship/'+m.id,'Edit offer','btn secondary small')}${btn(icon('trash'),'delete-mentorship','danger small',`data-id="${m.id}" aria-label="Delete offer"`)}</div></div></article>`).join('')}</div><h3 style="margin:32px 0 24px">Session requests</h3>${bookingTable(db.bookings.filter(b=>b.type==='mentorship'))}`,true)}
function bookingTable(items){return `<div class="table-wrap"><table><thead><tr><th>Learner</th><th>Session</th><th>Date / time</th><th>Status</th><th>Action</th></tr></thead><tbody>${items.map(b=>`<tr><td>${esc(b.name)}<small>${esc(b.email)}</small></td><td>${esc(b.title)}</td><td>${esc(b.date)}<small>${esc(b.time)} ${esc(b.timezone)}</small></td><td>${badge(b.status||'Confirmed','green')}</td><td>${b.type==='mentorship'?btn('Update status','booking-status','secondary small',`data-id="${b.id}"`):'Payment managed'}</td></tr>`).join('')||'<tr><td colspan="5">No bookings yet. Try a booking from the public mentorship page.</td></tr>'}</tbody></table></div>`}
function usersPage(team=false){if(team&&role!=='super')return shell(empty('This space belongs to the Super Admin.','Only the Super Admin manages other administrators.','Back to studio','/admin','shield'),true);let users=db.users.filter(u=>team?u.role!=='Learner':u.role==='Learner');return shell(`${shellTitle(team?'Your people behind the scenes.':'The people you’re helping grow.',team?'Only the Super Admin can invite, change or remove administrators.':'Manage learner access and course enrolments.',btn(`${icon('plus')} ${team?'Add admin':'Add learner'}`,'add-user','',`data-team="${team}"`))}<div class="notice" style="margin-bottom:24px">${team?'Only the owner can manage administrators. Every change is checked by the backend and logged.':'Admins manage learner access. Admin-team permissions are reserved for the Super Admin.'}</div><div class="table-wrap"><table><thead><tr><th>Name / email</th><th>Role</th><th>Access</th><th>Actions</th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td>${badge(u.role,u.role==='Super Admin'?'yellow':'blue')}</td><td>${badge(u.status,u.status==='Active'?'green':'red')}</td><td><div class="row">${u.role==='Super Admin'?'<small class="muted">Owner · protected</small>':`${btn('Edit','edit-user','secondary small',`data-id="${u.id}"`)}${btn(u.status==='Active'?'Suspend':'Restore','toggle-user','secondary small',`data-id="${u.id}"`)}`}</div></td></tr>`).join('')}</tbody></table></div>${!team?'<p class="form-note" style="margin-top:20px">Suspension blocks account access. Manual course grants are stored alongside paid enrolments.</p>':''}`,true)}
function orders(){return shell(`${shellTitle('The details behind every purchase.','Review purchases and workshop registrations stored in Firebase.',role==='super'?btn('Finish payment setup','payment-setup','secondary'):'')}${stats([[db.transactions.length,'Orders','wallet','Recorded purchases'],[money(db.transactions.reduce((s,t)=>s+t.amount,0)),'Order value','chart','All recorded orders'],[db.bookings.filter(b=>b.type==='workshop').length,'Workshop registrations','calendar','Demo confirmed'],[db.bookings.filter(b=>b.type==='mentorship').length,'Mentorship requests','users','Personal sessions']])}<div class="table-wrap" style="margin-top:32px"><table><thead><tr><th>Order</th><th>Item</th><th>Date & time</th><th>Amount</th><th>Status</th><th>Receipt</th></tr></thead><tbody>${db.transactions.map(t=>`<tr><td>${esc(t.id)}</td><td>${esc(t.title)}</td><td>${new Date(t.date).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})}</td><td>${money(t.amount)}</td><td>${badge(t.status,'green')}</td><td>${btn(icon('download'),'receipt','secondary small',`data-id="${t.id}" aria-label="Download receipt"`)}</td></tr>`).join('')}</tbody></table></div><h3 style="margin:32px 0 24px">Workshop registrations</h3>${bookingTable(db.bookings.filter(b=>b.type==='workshop'))}`,true)}
function discussions(){return shell(`${shellTitle('A good learning space is a conversation.','Reply to learners, add guidance and moderate discussions.',btn(`${icon('plus')} Add tutor note`,'tutor-comment'))}<div class="stack">${db.comments.map(c=>`<article class="card pad"><div class="between"><div><strong style="font-size:12px">${esc(c.name)}</strong><small class="muted" style="display:block;margin-top:8px">${esc(c.date)}</small></div>${btn(icon('trash'),'delete-comment','danger small',`data-id="${c.id}" aria-label="Remove comment"`)}</div><small class="muted">Course: ${esc(c.courseId)}</small><p style="font-size:13px;margin-top:20px">${esc(c.text)}</p>${btn('Reply','reply-comment','secondary small',`data-id="${c.id}"`)}</article>`).join('')||empty('The conversation starts with you.','Post a welcome note to help learners feel at home.','','','message')}</div>`,true)}
async function loadMedia(){if(!media.length){try{media=[...await(await fetch('assets/manifest.json')).json(),...await(await fetch('assets/generated/library.json')).json()]}catch{media=[]}}}
function mediaPage(){return shell(`${shellTitle('Every image. A little history.','All 36 archive images, plus 10 original images generated for MUXION.',btn(`${icon('plus')} Upload image`,'upload-media'))}<div class="notice" style="margin-bottom:24px">The archive contains images, but no embedded course videos or usable course video URLs. The only MP4 URL is an example placeholder. Add original videos in the course editor. This library preserves every extracted image, including original transparent assets.</div><div class="media-grid">${[...media,...(db.uploads||[])].map(m=>`<article class="media-item"><a href="${esc(m.file)}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(m.file)}" alt="${esc(m.original)}"></a><p>${esc(m.original)}<br>${Math.round(m.bytes/1024)} KB<br><a class="text-link" href="${esc(m.file)}" download>Download original ↗</a></p></article>`).join('')}</div>`,true)}
function contentPage(){return shell(`${shellTitle('The words that welcome people in.','Manage reusable FAQs and review original learner testimonials.',btn(`${icon('plus')} Add FAQ`,'add-faq'))}<section class="editor-section"><h3>Frequently asked questions</h3>${db.faqs.map((f,i)=>`<div class="settings-row"><div><h4>${esc(f.q)}</h4><p>${esc(f.a)}</p></div><div class="row">${btn(icon('edit'),'edit-faq','secondary small',`data-index="${i}" aria-label="Edit FAQ"`)}${btn(icon('trash'),'delete-faq','danger small',`data-index="${i}" aria-label="Delete FAQ"`)}</div></div>`).join('')}</section><section class="editor-section"><h3>Original testimonials · recovered from Make</h3><p class="form-note">These quotations are preserved from the Make source history. Confirm permission and accuracy before live publication.</p>${testimonials.map(t=>`<div class="settings-row"><div><h4>${esc(t.name)} · ${esc(t.role)}</h4><p>${esc(t.text)}</p></div></div>`).join('')}</section>`,true)}
function enquiries(){return shell(`${shellTitle('Every conversation starts somewhere.','Build requests, school learning enquiries and mentorship questions.')}${(db.enquiries||[]).length?`<div class="stack">${db.enquiries.map(e=>`<article class="card pad"><div class="between">${badge(e.interest||'General enquiry','blue')}<small class="muted">${new Date(e.date).toLocaleDateString('en-IN')}</small></div><h3 style="margin:16px 0 8px">${esc(e.name)}</h3><a class="text-link" href="mailto:${esc(e.email)}">${esc(e.email)}</a><p class="muted" style="font-size:12px;margin-top:16px">${esc(e.message)}</p><div style="margin-top:20px">${btn(e.closed?'Reopen':'Mark handled','enquiry-status','secondary small',`data-id="${e.id}"`)}</div></article>`).join('')}</div>`:empty('Your next conversation will appear here.','Try an enquiry from Build with MUXION, mentorship or the contact page.','','','mail')}`,true)}
function checkout(workshopId=''){const workshop=workshopId?wBy(workshopId):null,items=workshop?[workshop]:cart.map(cBy).filter(Boolean),subtotal=items.reduce((s,c)=>s+Number(c.price),0);if(!items.length)return publicPage(`<div class="container section">${empty('Make room for your next skill.','Your bag is empty. Find a course that gets your curiosity going.','Explore courses','/courses','book')}</div>`);return publicPage(`<div class="container section"><div class="breadcrumb">${link('/courses','Explore')} / Your next move</div><h1 class="detail-title">A good investment.<br><span class="blue">In you.</span></h1><div class="detail-grid"><div><div class="stack">${items.map(c=>`<article class="card cart-line">${art(c,workshop?'live':'')}<div><h3>${esc(c.title)}</h3><p class="muted" style="font-size:11px;margin-top:8px">${workshop?formatWorkshop(workshop):'Lifetime access · Self-paced learning'}</p>${!workshop?btn('Remove','remove-cart','secondary small',`data-id="${c.id}" style="margin-top:12px"`):''}</div><span class="price">${money(c.price)}</span></article>`).join('')}</div><div class="notice" style="margin-top:24px">${paymentConfig.mode==='live'?'Live payment: real money will be charged.':'Test Mode: no real money is charged.'} Prices are checked by the server. Your purchase is linked to your signed-in account. Course access unlocks after the backend confirms a captured payment.</div></div><aside class="card pad"><h3>Your next chapter</h3><div class="settings-row"><span class="muted">Subtotal</span><span>${money(subtotal)}</span></div><p class="form-note" style="margin:20px 0">Momentum discounts will unlock after points can be verified by the backend.</p><div class="between" style="margin:24px 0"><strong>Total · INR</strong><span class="price" id="checkout-total">${money(subtotal)}</span></div><p class="form-note" style="margin:16px 0">INR checkout. Payment details are handled by Razorpay. MUXION never receives your card number or CVV.</p><p class="form-note" style="margin:16px 0">By choosing Pay, you agree to the ${link('/terms','Terms of service')} and ${link('/refunds','Refund and cancellation policy')}, and acknowledge the ${link('/privacy','Privacy policy')}. ${workshop?'Cancel at least 24 hours before the start for a full refund.':'Course refunds: request within 7 days, no more than 20% completed and no certificate issued.'}</p>${btn(`Pay with Razorpay${paymentConfig.mode==='test'?' · Test':''} ${icon('arrow')}`,'checkout','full',`data-workshop="${workshopId}" data-subtotal="${subtotal}"`)}</aside></div></div>`)}
function checkoutSuccess(){const receipt=razorpayReceipt;if(!receipt)return publicPage(`<div class="container section" style="max-width:760px"><div class="eyebrow">Payment verification</div><h1 class="detail-title">No verified receipt<br>in this session yet.</h1><p class="muted" style="margin:24px 0">A success URL never confirms payment. Refresh after a captured payment to recover your verified receipt. If you paid from another browser, contact hello@muxion.in with your payment ID.</p>${link('/courses','Explore courses','btn')}</div>`);const test=receipt.mode==='test';return publicPage(`<div class="container section" style="max-width:760px"><div class="eyebrow">RAZORPAY / ${test?'TEST MODE':'PAYMENT CONFIRMED'}</div><h1 class="detail-title">${test?'Test payment':'Your payment'}<br><span class="blue">verified.</span></h1><p class="muted" style="margin:24px 0">${test?'No real money was charged.':'Thank you. Razorpay confirmed that your payment was captured.'}</p><div class="card pad stack" style="overflow-wrap:anywhere"><div><small class="muted">ORDER ID</small><p>${esc(receipt.order_id)}</p></div><div><small class="muted">PAYMENT ID</small><p>${esc(receipt.payment_id)}</p></div><div><small class="muted">TOTAL</small><p>${money(receipt.amount/100)} · ${esc(receipt.currency)}</p></div>${receipt.items.map(i=>`<p>${esc(i.title)}</p>`).join('')}</div><div class="notice" style="margin:24px 0">Your purchase and access have been saved to your account. A refunded purchase loses access automatically. Contact hello@muxion.in with your payment ID if you need help.</div>${link('/learner/courses','Open my courses','btn')}</div>`)}

function legal(kind){return publicPage(`<div class="container section" style="max-width:900px">${policyContent(kind)}</div>`)}
function pageMap(){const pages=[['Public website',[['/','MUXION home · Build'],['/learn','MUXION Learn'],['/academy','Academy home'],['/courses','Course catalogue'],['/course/mastery','Course invite & curriculum'],['/workshops','Workshops'],['/workshop/design-lab','Workshop details'],['/mentorship','Mentorship & packages'],['/mentorship/book','Book a session'],['/about','About Mariam'],['/contact','Contact'],['/checkout','Shopping bag & checkout'],['/checkout/success','Demo purchase complete'],['/verify','Certificate verification'],['/privacy','Privacy policy'],['/terms','Terms of service'],['/refunds','Refund and cancellation policy']]],['Account & sign-in',[['/login','Learner login'],['/signup','Create account'],['/forgot-password','Forgot password'],['/reset-password','Reset password'],['/login/admin','Admin login']]],['Learner',learnerNav.map(([p,t])=>[p,t]).concat([['/learner/learn/mastery','Course learning workspace'],['/learner/notifications','Notifications']])],['Teaching studio',adminNav.map(([p,t])=>[p,t]).concat([['/admin/courses/new','Create course'],['/admin/courses/mastery','Course & curriculum editor'],['/admin/workshops/new','Create workshop'],['/admin/workshops/design-lab','Workshop editor'],['/admin/mentorship/new','Create mentorship'],['/admin/team','Super Admin team management'],['/admin/notifications','Notifications']])]];return publicPage(`<div class="container section"><div class="eyebrow">A complete tour</div><h1 class="detail-title">Every little corner<br><span class="blue">of MUXION.</span></h1><p class="muted">Sign in to open your learning portal. Teaching studio access requires an authorised account.</p><div class="row wrap" style="margin:24px 0 40px">${btn('Learner sign-in','demo-learner')}${btn('Admin sign-in','demo-admin','secondary')}${btn('Owner sign-in','demo-super','secondary')}</div><div class="grid2">${pages.map(([title,items])=>`<section class="card pad"><h3 style="margin-bottom:24px">${title}</h3><div class="stack" style="gap:12px">${items.map(([p,t])=>link(p,`${t} ${icon('arrow')}`,'text-link')).join('')}</div></section>`).join('')}</div></div>`)}
function safeUrl(url){try{const u=new URL(url);return ['https:','http:','blob:'].includes(u.protocol)?esc(url):'#'}catch{return '#'}}
function showDialog(title,body){$('#dialog').innerHTML=`<div class="dialog-head"><h2>${title}</h2><button class="close-dialog" data-action="close-dialog" aria-label="Close dialog">×</button></div>${body}`;$('#dialog').showModal()}
function confirmAction(title,message,action,id){showDialog(title,`<p>${message}</p><div class="form-actions">${btn('Keep it','close-dialog','secondary')}${btn('Confirm','confirmed','danger',`data-confirm="${action}" data-id="${esc(id)}"`)}</div>`)}
function formValues(form){return Object.fromEntries(new FormData(form))}
const lines=value=>String(value||'').split('\n').map(x=>x.trim()).filter(Boolean);
function captureCourse(){const form=$('#course-form');if(!form||!draftCourse)return;const f=formValues(form);Object.assign(draftCourse,{title:f.title,subtitle:f.subtitle,category:f.category,level:f.level,language:f.language,tutor:f.tutor,description:f.description,outcomes:lines(f.outcomes),audience:f.audience,requirements:f.requirements,status:f.status,price:Number(f.price),original:Number(f.original),quiz:{question:f.quizQuestion,options:[f.option0,f.option1,f.option2],answer:Number(f.quizAnswer)-1}})}
async function saveCourse(){const form=$('#course-form');if(!form?.reportValidity())return;captureCourse();const c=clone(draftCourse);delete c._key;const {offer}=await platformRequest('admin-offer',{body:{kind:'course',...c}});const i=db.courses.findIndex(x=>x.id===offer.id);if(i<0)db.courses.push(offer);else db.courses[i]=offer;draftCourse=null;go('/admin/courses');toast('Course and checkout price saved to Firebase.')}
function lessonDialog(index=-1){captureCourse();const l=draftCourse.lessons[index]||{id:'l'+crypto.randomUUID().slice(0,8),title:'',section:'Start here',type:'video',minutes:10,url:'',body:''};showDialog(index<0?'A new little chapter.':'Fine-tune this lesson.',`<form id="lesson-form" data-index="${index}" data-id="${l.id}"><div class="form-grid">${input('Lesson title','title',l.title,'text',true)}${input('Chapter / section','section',l.section,'text',true)}${select('Content type','type',l.type,['video','resource','quiz','assignment'])}${input('Estimated minutes','minutes',l.minutes,'number',true,'min="1"')}${input('Video or resource URL','url',l.url?.startsWith('blob:')?'':l.url,'url')}${area('Resource text / assignment brief / tutor notes','body',l.body,'class="wide"')}<label class="wide">Or upload a video / study file<input type="file" name="file" accept="video/*,.pdf,.txt,.docx,.pptx,.png,.jpg"></label></div><p class="form-note">Uploaded files are stored in this browser’s IndexedDB for the preview. They are not sent to a server. Add a quiz question in the course editor for quiz lessons.</p><button class="btn" type="submit">Save lesson ${icon('check')}</button></form>`)}
async function putFile(id,file){const database=await fileDatabase();return new Promise((resolve,reject)=>{const tx=database.transaction('files','readwrite');tx.objectStore('files').put(file,id);tx.oncomplete=()=>{database.close();resolve()};tx.onerror=()=>reject(tx.error)})}
function fileDatabase(){return new Promise((resolve,reject)=>{const req=indexedDB.open('muxion-preview-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function hydrateFiles(){try{const database=await fileDatabase();for(const c of db.courses){for(const l of c.lessons){if(l.mediaId){const blob=await new Promise((resolve,reject)=>{const req=database.transaction('files').objectStore('files').get(l.mediaId);req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});l.url=blob?URL.createObjectURL(blob):''}}}database.close()}catch{}}
function userDialog(id,team=false){const u=db.users.find(u=>u.id===id)||{id:'u'+crypto.randomUUID().slice(0,8),name:'',email:'',role:team?'Admin':'Learner',status:'Active'};if(u.id==='owner')return toast('The Super Admin owner is protected.');if((team||u.role!=='Learner')&&role!=='super')return toast('Only the Super Admin can manage admins.');showDialog(id?'Update access.':team?'Make room for an admin.':'Welcome a learner.',`<form id="user-form" data-id="${u.id}" data-team="${team||u.role!=='Learner'}">${input('Full name','name',u.name,'text',true)}${input('Email','email',u.email,'email',true)}${team||u.role!=='Learner'?select('Role','role',u.role,['Admin','Learner']):'<input name="role" type="hidden" value="Learner">'}${select('Access','status',u.status,['Active','Suspended'])}${!team&&u.role==='Learner'?`<label><input name="revokeManual" type="checkbox"> Revoke manual access to the selected course (paid purchases remain active)</label><label>Course enrolments<select name="course"><option value="">No change to course access</option>${db.courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></label>`:''}<p class="form-note">Changes apply to the real Firebase account. New users sign in with Google using this email; invitation emails are not sent.</p><button class="btn" type="submit">Save access</button></form>`)}
function enquiryDialog(type){showDialog(type==='Build with MUXION'?'Let’s make it happen.':type==='MUXION Learning'?'Find your learning plan.':'Your next step, together.',`<p>${type==='Build with MUXION'?'Tell me about the idea you can’t stop thinking about.':'Tell us where you are and what you’d like to work toward.'}</p><form id="enquiry-form" action="https://formsubmit.co/hello@muxion.in" method="POST" data-email-delivery="formsubmit"><input type="hidden" name="_subject" value="New MUXION website enquiry"><input type="hidden" name="_template" value="table"><div hidden><label>Leave this field empty<input name="_honey" tabindex="-1" autocomplete="off"></label></div><input type="hidden" name="interest" value="${type}">${input('Your name','name',role==='learner'?db.profile.name:'','text',true)}${input('Email address','email',role==='learner'?db.profile.email:'','email',true)}${type==='Build with MUXION'?`${select('What are we building?','project',['Website'][0],['Website','Web app','Mobile app','Custom software','Let’s figure it out'])}${select('Indicative budget','budget','Let’s discuss',['Let’s discuss','Under ₹25,000','₹25,000–₹1,00,000','₹1,00,000+'])}`:''}${area(type==='MUXION Learning'?'Grade, board, subjects & learning goals':'A little about your idea or goals','message','')}<button class="btn" type="submit">Send enquiry ${icon('arrow')}</button><p class="form-note">Your enquiry is sent via FormSubmit to hello@muxion.in. <a href="/privacy" target="_blank" rel="noopener">How we use your information</a>. You may be asked to complete a spam check.</p></form>`)}
function takeQuiz(id){const c=cBy(id);if(!c.quiz.question)return toast('Your tutor hasn’t added the quiz question yet.');showDialog('A little design thinking.',`<form id="quiz-form" data-id="${id}"><p>${esc(c.quiz.question)}</p>${c.quiz.options.map((o,i)=>`<label class="card pad" style="display:flex;align-items:center;gap:12px"><input name="answer" type="radio" value="${i}" required>${esc(o)}</label>`).join('')}<button class="btn" type="submit">Check my answer</button><div id="quiz-feedback" role="status"></div></form>`)}
async function completeLesson(id,lid){const c=cBy(id),l=c?.lessons.find(l=>l.id===lid);if(!l)return;if(l.type==='quiz'&&!db.quizPassed.includes(id+':'+lid))return takeQuiz(id);const result=await platformRequest('learning-progress',{body:{courseId:id,lessonId:lid,action:'complete'}});await refreshAccount();render();if(result.certificate){showDialog('Look what you made possible. ✳',`<p>Your completion is verified and your certificate is saved to your account.</p>${link('/learner/certificates','Meet your certificate','btn')}`);}else toast('Lesson completion saved to your account.');}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const d=document.createElement('div');d.className='confetti';d.innerHTML=Array.from({length:65},(_,i)=>`<i style="left:${Math.random()*100}%;background:${['#51a2ff','#f7df49','#a8e6cf','#c8b0ff'][i%4]};animation-delay:${Math.random()}s;transform:rotate(${Math.random()*180}deg)"></i>`).join('');document.body.append(d);setTimeout(()=>d.remove(),5000)}
function downloadBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function textWrap(ctx,text,x,y,width,lineHeight){const words=text.split(/\s+/);let line='';for(const w of words){if(ctx.measureText(line+w).width>width&&line){ctx.fillText(line.trim(),x,y);y+=lineHeight;line=''}line+=w+' '}ctx.fillText(line.trim(),x,y);return y+lineHeight}
async function certificateCanvas(cert){await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=2000;canvas.height=1414;const x=canvas.getContext('2d');x.fillStyle='#f5f0e6';x.fillRect(0,0,2000,1414);x.strokeStyle='#b8b8a3';x.lineWidth=2;x.strokeRect(52,52,1896,1310);x.strokeRect(68,68,1864,1278);x.textAlign='center';x.fillStyle='#2366bb';x.font='600 60px "Be Vietnam Pro",sans-serif';x.fillText('MUXION',1000,225);x.fillStyle='#56647a';x.font='400 26px "Be Vietnam Pro",sans-serif';x.fillText('C E R T I F I C A T E   O F   C O M P L E T I O N',1000,355);x.font='400 26px "Be Vietnam Pro",sans-serif';x.fillText('This celebrates the curiosity and commitment of',1000,465);x.fillStyle='#12213d';x.font='600 78px "Be Vietnam Pro",sans-serif';textWrap(x,cert.name,1000,610,1660,100);x.fillStyle='#56647a';x.font='400 26px "Be Vietnam Pro",sans-serif';x.fillText('who has completed all required elements of',1000,790);x.fillStyle='#12213d';x.font='500 44px "Be Vietnam Pro",sans-serif';textWrap(x,cert.course,1000,890,1660,60);x.fillStyle='#a47f28';x.font='80px sans-serif';x.fillText('✳',1000,1090);x.strokeStyle='#b8b8a3';x.beginPath();x.moveTo(180,1180);x.lineTo(1820,1180);x.stroke();x.font='400 21px "Be Vietnam Pro",sans-serif';x.fillStyle='#56647a';x.textAlign='left';x.fillText('Mariam Parvez / Founder & Mentor',180,1240);x.textAlign='right';x.fillText(cert.date+' / '+cert.id,1820,1240);return canvas}
async function downloadCertificate(id,format){const cert=db.certificates.find(c=>c.id===id);if(!cert)return;const canvas=await certificateCanvas(cert);if(format==='pdf'){const jpeg=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.96));const imageBytes=new Uint8Array(await jpeg.arrayBuffer());const enc=new TextEncoder();let chunks=[],offsets=[0],length=0;const add=data=>{const b=typeof data==='string'?enc.encode(data):data;chunks.push(b);length+=b.length};add('%PDF-1.4\n');function obj(n,body){offsets[n]=length;add(`${n} 0 obj\n${body}\nendobj\n`)}obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,'<< /Type /Pages /Kids [3 0 R] /Count 1 >>');obj(3,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /XObject << /Im1 4 0 R >> >> /Contents 5 0 R >>');offsets[4]=length;add(`4 0 obj\n<< /Type /XObject /Subtype /Image /Width 2000 /Height 1414 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${imageBytes.length} >>\nstream\n`);add(imageBytes);add('\nendstream\nendobj\n');const content='q 842 0 0 595 0 0 cm /Im1 Do Q';obj(5,`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);const start=length;add('xref\n0 6\n0000000000 65535 f \n');for(let i=1;i<6;i++)add(String(offsets[i]).padStart(10,'0')+' 00000 n \n');add(`trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`);downloadBlob(new Blob(chunks,{type:'application/pdf'}),cert.id+'.pdf')}else canvas.toBlob(b=>downloadBlob(b,cert.id+'.'+format),format==='jpg'?'image/jpeg':'image/png',.96);toast('Your certificate is ready to download.')}
async function poster(id){const w=wBy(id);showDialog('One workshop. A little buzz.',`<div class="poster-preview"><div><span class="poster-star">✳</span><small>MUXION / LIVE DESIGN LAB</small><h2 style="margin:48px 0 20px">${esc(w.title)}</h2><p style="color:#bfd2ef">${esc(w.topic)}</p></div><div><small>${formatWorkshop(w)}</small><h3 style="margin:12px 0">${money(w.price)} · ${w.duration} minutes</h3><small>WITH ${esc(w.tutor).toUpperCase()} / MUXION.IN</small></div></div><div class="form-actions">${btn(`${icon('download')} Download 2160 × 2160 PNG`,'download-poster','',`data-id="${id}"`)}</div>`)}
async function downloadPoster(id){const w=wBy(id);await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=canvas.height=2160;const x=canvas.getContext('2d');x.fillStyle='#142d53';x.fillRect(0,0,2160,2160);x.strokeStyle='#36547c';for(let i=0;i<2160;i+=120){x.beginPath();x.moveTo(i,0);x.lineTo(i,2160);x.moveTo(0,i);x.lineTo(2160,i);x.stroke()}x.fillStyle='#f7df49';x.font='240px sans-serif';x.fillText('✳',1730,360);x.fillStyle='#b7d1f8';x.font='500 35px "Be Vietnam Pro",sans-serif';x.fillText('MUXION / LIVE DESIGN LAB',160,220);x.fillStyle='#f1f5f9';x.font='600 128px "Be Vietnam Pro",sans-serif';let y=textWrap(x,w.title,160,600,1800,170);x.fillStyle='#bbcee9';x.font='400 48px "Be Vietnam Pro",sans-serif';textWrap(x,w.topic,160,y+80,1650,75);x.fillStyle='#f7df49';x.fillRect(160,1510,1840,2);x.fillStyle='#f1f5f9';x.font='500 70px "Be Vietnam Pro",sans-serif';x.fillText(money(w.price)+' / '+w.duration+' MINUTES',160,1660);x.font='400 38px "Be Vietnam Pro",sans-serif';x.fillText(formatWorkshop(w),160,1770);x.fillStyle='#b7d1f8';x.font='400 36px "Be Vietnam Pro",sans-serif';x.fillText('WITH '+w.tutor.toUpperCase(),160,1890);x.fillText('SAVE YOUR SEAT / MUXION.IN',160,2010);canvas.toBlob(b=>downloadBlob(b,'MUXION-'+id+'-instagram.png'),'image/png');toast('Your high-resolution workshop creative is ready.')}
function receipt(id){const t=db.transactions.find(t=>t.id===id);if(!t)return;downloadBlob(new Blob([`MUXION — PAYMENT ACKNOWLEDGEMENT\nNot a tax invoice.\n\nOrder: ${t.id}\nPayment: ${t.paymentId}\nPurchase: ${t.title}\nAmount: ${money(t.amount)}\nDate: ${t.date}\nStatus: ${t.status}\nMode: ${t.mode}\n\nhello@muxion.in | +91 77081 00469`],{type:'text/plain;charset=utf-8'}),t.id+'-receipt.txt')}
document.addEventListener('click',async event=>{const policyAnchor=event.target.closest('[data-policy-section]');if(policyAnchor){event.preventDefault();const section=document.getElementById('policy-section-'+policyAnchor.dataset.policySection);section?.setAttribute('tabindex','-1');section?.focus({preventScroll:true});section?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});return;}if(event.target.closest('.skip')){event.preventDefault();$('#main').setAttribute('tabindex','-1');$('#main').focus();return}const a=event.target.closest('[data-action]');if(!a)return;const action=a.dataset.action,id=a.dataset.id;try{
switch(action){
case 'mobile-menu':$('.navlinks').classList.toggle('open');break;
case 'close-dialog':$('#dialog').close();break;
case 'demo-learner':case 'demo-admin':case 'demo-super':go('/login');toast('Sign in to access your account.');break;
case 'logout':await signOutAccount();role='';sessionStorage.removeItem('muxion.role');go('/login');break;
case 'google-demo':{const entryPath=route();a.disabled=true;a.setAttribute('aria-busy','true');try{await signInGoogle();await finishSignIn(entryPath);}finally{a.disabled=false;a.removeAttribute('aria-busy');}break;}
case 'more-payments':{const more=await platformRequest('payment-history',{query:{cursor:paymentHistoryCursor}});const known=new Set(db.transactions.map(t=>t.id));db.transactions.push(...mapOrders(more.orders).filter(t=>!known.has(t.id)));paymentHistoryCursor=more.nextCursor;render();break;}
case 'payment-setup':{a.disabled=true;try{await platformRequest('admin-payment-setup',{body:{}});toast('Razorpay payment and refund webhooks are active.');}catch(error){toast(error.message);}finally{a.disabled=false;}break;}
case 'verify-email':await sendVerification();toast('Verification email sent. Follow its link, then sign in again.');break;
case 'filter':filter=a.dataset.value;render();break;
case 'wishlist':if(db.wishlist.includes(id))db.wishlist=db.wishlist.filter(x=>x!==id);else db.wishlist.push(id);save();render();toast(db.wishlist.includes(id)?'A little possibility saved for later.':'Removed from your wishlist.');break;
case 'expand-all':document.querySelectorAll('.accordion').forEach(d=>d.open=true);break;
case 'preview-lesson':{const l=cBy(a.dataset.course)?.lessons.find(l=>l.id===id);showDialog('A peek at your next chapter.',`<h3>${esc(l.title)}</h3><p style="margin-top:16px">${l.url?'The video is available in the demo learning workspace.':'The original preview video is not embedded in this archive. Add it in the admin course editor to activate playback.'}</p>${link('/login','Explore the learner demo →','btn')}`);break}
case 'add-cart':if(!cart.includes(id))cart.push(id);go('/checkout');break;
case 'remove-cart':cart=cart.filter(x=>x!==id);render();break;
case 'workshop-checkout':go('/checkout/workshop/'+id);break;
case 'checkout':{if(!currentUser){sessionStorage.setItem('muxion.returnTo',route());go('/login');toast('Sign in to connect your purchase to your account.');break;}if(!currentUser.emailVerified){showDialog('Verify your email before paying.',`<p>Use the verification link in your email, or sign in with Google.</p>${btn('Send verification email','verify-email')}`);break;}if(a.disabled)break;a.disabled=true;a.setAttribute('aria-busy','true');const original=a.innerHTML;a.textContent='Opening Razorpay…';try{const wid=a.dataset.workshop,items=wid?['workshop:'+wid]:cart.map(id=>'course:'+id);const result=await startRazorpayCheckout({items,amount:Math.round(Number(a.dataset.subtotal)*100)});if(result.cancelled){toast('Checkout cancelled. You can try again when you’re ready.')}else if(result.success){razorpayReceipt=result;await refreshAccount();cart=[];go('/checkout/success')}else{showDialog('Payment is awaiting confirmation.',`<p>${esc(result.message||'The payment is not captured yet. No access has been granted.')}</p><p class="form-note">Order: ${esc(result.order_id)}</p><a class="btn secondary" href="mailto:hello@muxion.in">Contact MUXION</a>`)}}catch(error){showDialog('Checkout needs your attention.',`<p>${esc(error.message)}</p>${btn('Close','close-dialog','secondary')}`)}finally{a.disabled=false;a.removeAttribute('aria-busy');a.innerHTML=original}break}
case 'enquiry':enquiryDialog('Personal mentorship');break;case 'build-enquiry':enquiryDialog('Build with MUXION');break;case 'school-enquiry':enquiryDialog('MUXION Learning');break;
case 'learner-tab':case 'payment-tab':tab=a.dataset.value;render();break;
case 'player-tab':playerTab=a.dataset.value;if(playerTab==='discussion')await loadDiscussion(route().split('/')[3]);render();break;
case 'select-lesson':lessonId=id;render();break;
case 'next-lesson':case 'prev-lesson':{const c=cBy(id),i=c.lessons.findIndex(l=>l.id===lessonId);lessonId=c.lessons[Math.min(c.lessons.length-1,Math.max(0,i+(action==='next-lesson'?1:-1)))].id;playerTab='overview';render();break}
case 'complete-lesson':await completeLesson(id,a.dataset.lesson);break;
case 'save-notes':{const f=$('#notes-form'),[courseId,lessonId]=f.dataset.id.split(':');await platformRequest('learning-progress',{body:{courseId,lessonId,action:'note',note:f.elements.notes.value}});await refreshAccount();toast('Private notes saved to your account.');break}
case 'take-quiz':takeQuiz(id);break;
case 'timer-toggle':if(!db.enrolled.length)return toast('Enrol in a course to start Momentum.');if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.running=false}else{timer.end=Date.now()+timer.remaining*1000;timer.running=true}render();break;
case 'timer-reset':timer={phase:'focus',remaining:2700,running:false,end:0,focusDone:false};render();break;
case 'download-cert':{const {certificate}=await platformRequest('certificate-verify',{query:{id}});if(certificate?.status!=='Valid')throw Error('This certificate is not currently valid.');await downloadCertificate(id,a.dataset.format);break;}
case 'revoke-cert':await platformRequest('certificate-revoke',{body:{id}});verificationCache.delete(id);await refreshAccount();render();toast('Certificate revoked.');break;
case 'receipt':receipt(id);break;
case 'change-password':showDialog('A fresh password.',`<form id="password-form">${input('Current password','current','','password',true,'minlength="8"')}${input('New password','password','','password',true,'minlength="8"')}${input('Confirm new password','confirm','','password',true,'minlength="8"')}<button class="btn" type="submit">Preview password change</button><p class="form-note">No passwords are stored or changed. Firebase will handle this securely in phase two.</p></form>`);break;
case 'export-data':downloadBlob(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),'muxion-demo-data.json');break;
case 'reset-demo':confirmAction('Start this demo fresh?','This clears local progress, edits, bookings and profile details and restores the seeded content.','reset','');break;
case 'reschedule':{const b=db.bookings.find(b=>b.id===id);showDialog('Let’s find another time.',`<form id="reschedule-form" data-id="${id}">${input('Preferred date','date',b.date,'date',true)}${input('Preferred time','time',b.time,'time',true)}<button class="btn" type="submit">Request a new time</button></form>`);break}
case 'save-course':await saveCourse();break;
case 'add-lesson':lessonDialog();break;case 'edit-lesson':lessonDialog(Number(a.dataset.index));break;
case 'remove-lesson':captureCourse();draftCourse.lessons.splice(Number(a.dataset.index),1);render();break;
case 'move-lesson':{captureCourse();const i=Number(a.dataset.index),j=i+Number(a.dataset.direction);if(j>=0&&j<draftCourse.lessons.length){[draftCourse.lessons[i],draftCourse.lessons[j]]=[draftCourse.lessons[j],draftCourse.lessons[i]];render()}break}
case 'delete-course':confirmAction('Remove this course?','This deletes the local demo course and its local progress. It does not affect the original Make file.','course',id);break;
case 'delete-workshop':confirmAction('Remove this workshop?','This removes the workshop from the local preview.','workshop',id);break;
case 'delete-mentorship':confirmAction('Remove this offer?','This hides the offer from new session requests. Existing bookings are preserved.','mentorship',id);break;
case 'confirmed':{const type=a.dataset.confirm;if(type==='reset'){db=clone(seed);timer={phase:'focus',remaining:2700,running:false,end:0,focusDone:false};draftCourse=null;draftWorkshop=null;try{indexedDB.deleteDatabase('muxion-preview-files')}catch{}}else if(type==='course'){db.courses=db.courses.filter(c=>c.id!==id);db.enrolled=db.enrolled.filter(x=>x!==id);db.wishlist=db.wishlist.filter(x=>x!==id);db.completed=db.completed.filter(x=>!x.startsWith(id+':'));draftCourse=null}else if(type==='workshop'){db.workshops=db.workshops.filter(w=>w.id!==id);draftWorkshop=null}else if(type==='mentorship'){const m=db.mentorships.find(m=>m.id===id);await platformRequest('mentorship-save',{body:{...m,status:'Draft'}});await refreshAccount();}save();$('#dialog').close();render();toast('Changes saved.');break}
case 'poster':await poster(id);break;case 'download-poster':await downloadPoster(id);break;
case 'add-user':userDialog('',a.dataset.team==='true');break;case 'edit-user':userDialog(id);break;
case 'toggle-user':{const u=db.users.find(u=>u.id===id);await platformRequest('user-access',{body:{id,existing:true,name:u.name,email:u.email,role:u.role,status:u.status==='Active'?'Suspended':'Active'}});await refreshAccount();render();toast('Account access updated.');break;}
case 'booking-status':{const b=db.bookings.find(b=>b.id===id);showDialog('Update the session.',`<form id="booking-status-form" data-id="${id}">${select('Status','status',b.status,['Requested','Confirmed','Reschedule requested','Completed','Cancelled'])}${input('Google Meet / meeting URL','meet',b.meet||'','url')}<button class="btn" type="submit">Save session</button></form>`);break;}
case 'tutor-comment':showDialog('Guide the conversation.',`<form id="tutor-comment-form"><label>Course<select name="courseId" required>${db.courses.map(c=>`<option value="${c.id}">${esc(c.title)}</option>`).join('')}</select></label>${area('Tutor note','text','')}<button class="btn" type="submit">Post tutor note</button></form>`);break;
case 'reply-comment':{const comment=db.comments.find(c=>c.id===id);showDialog('Reply to the conversation.',`<form id="reply-form" data-id="${id}" data-course="${comment.courseId}">${area('Your reply','text','')}<button type="submit" class="btn">Post reply</button></form>`);break;}
case 'delete-comment':await platformRequest('discussion-remove',{body:{id}});await refreshAccount();render();toast('Message removed.');break;
case 'upload-media':showDialog('Add to your visual library.',`<form id="media-form"><label>Choose an image<input name="image" type="file" accept="image/*" required></label><p class="form-note">Images up to 2MB for the local preview.</p><button class="btn" type="submit">Add image</button></form>`);break;
case 'add-faq':case 'edit-faq':{const index=action==='add-faq'?-1:Number(a.dataset.index),f=db.faqs[index]||{q:'',a:''};showDialog('A little clarity.',`<form id="faq-form" data-index="${index}">${input('Question','q',f.q,'text',true)}${area('Answer','a',f.a)}<button class="btn" type="submit">Save FAQ</button></form>`);break}
case 'delete-faq':db.faqs.splice(Number(a.dataset.index),1);save();render();break;
case 'enquiry-status':{const e=db.enquiries.find(e=>e.id===id);e.closed=!e.closed;save();render();toast(e.closed?'Enquiry marked handled.':'Enquiry reopened.');break}
}}catch(err){console.error(err);toast('That action couldn’t finish. Please try again.')}});
document.addEventListener('submit',async event=>{const form=event.target;if(!(form instanceof HTMLFormElement))return;if(form.dataset.emailDelivery==='formsubmit'){const message=form.elements.namedItem('message');if(!message?.value.trim()){event.preventDefault();message?.setCustomValidity('Tell us a little about your enquiry.');message?.reportValidity();return}message.setCustomValidity('');return}event.preventDefault();const f=formValues(form),id=form.dataset.id;try{switch(form.id){
case 'login-form':{const entryPath=route();await signInEmail(f.email,f.password);form.reset();await finishSignIn(entryPath);break;}
case 'signup-form':await createAccount(f.name,f.email,f.password);form.reset();toast('Account created. Verify your email before purchasing, or use Google sign-in.');break;
case 'forgot-form':await resetPassword(f.email);form.reset();showDialog('Check your inbox.',`<p>If this email belongs to an account, Firebase will send a password reset link.</p>`);break;
case 'reset-form':toast('Open the secure password-reset link from your email to choose a password.');break;
case 'password-form':if(f.password!==f.confirm)return toast('Your new passwords don’t match.');form.reset();$('#dialog').close();toast('Form validated. Connect Firebase to change real passwords.');break;
case 'profile-form':await platformRequest('profile-save',{body:f});await currentUser.reload();await currentUser.getIdToken(true);await refreshAccount();render();toast('Profile saved to your account.');break;
case 'preferences-form':db.preferences={reminders:!!f.reminders,workshops:!!f.workshops,community:!!f.community};save();toast('Preferences saved. Email delivery comes with the backend.');break;
case 'site-settings-form':Object.assign(db.settings,f);save();toast('Your studio settings are saved locally.');break;
case 'booking-form':{if(!currentUser){sessionStorage.setItem('muxion.returnTo',route());go('/login');toast('Sign in before requesting a mentorship session.');break;}const offer=db.mentorships.find(m=>m.status==='Published');const key='muxion.bookingRequest.'+currentUser.uid;let requestId=sessionStorage.getItem(key);if(!requestId){requestId=crypto.randomUUID();sessionStorage.setItem(key,requestId);}await platformRequest('mentorship-book',{body:{offerId:offer.id,requestId,date:f.date,time:f.time,goals:f.goals}});sessionStorage.removeItem(key);await refreshAccount();go('/learner/mentorship');toast('Session requested. Your mentor will confirm it. No payment was collected.');break;}

case 'reply-form':await platformRequest('discussion-post',{body:{courseId:form.dataset.course,replyTo:id,text:f.text}});if(route().startsWith('/admin'))await refreshAccount();else await loadDiscussion(form.dataset.course);$('#dialog').close();render();toast('Reply posted.');break;
case 'comment-form':await platformRequest('discussion-post',{body:{courseId:route().split('/')[3],text:f.text}});await loadDiscussion(route().split('/')[3]);render();toast('Your message is posted.');break;
case 'tutor-comment-form':await platformRequest('discussion-post',{body:{courseId:f.courseId,text:f.text}});await refreshAccount();$('#dialog').close();render();toast('Tutor note posted.');break;
case 'assignment-form':await platformRequest('learning-progress',{body:{courseId:id,lessonId:form.dataset.lesson,action:'assignment',url:f.url}});await refreshAccount();toast('Project link saved to your account.');break;
case 'quiz-form':{const result=await platformRequest('learning-progress',{body:{courseId:id,lessonId,action:'quiz',answer:Number(f.answer)}});if(!result.correct){$('#quiz-feedback').innerHTML='<p class="notice">Not quite. Try again.</p>';return;}await refreshAccount();$('#dialog').close();render();toast('Quiz passed and completion saved.');break;}
case 'verify-form':go('/verify/'+encodeURIComponent(f.id.trim()));break;
case 'course-form':await saveCourse();break;
case 'lesson-form':{const index=Number(form.dataset.index),existing=draftCourse.lessons[index],l={id,title:f.title,section:f.section,type:f.type,minutes:Number(f.minutes),url:f.url,body:f.body};const file=form.elements.file.files[0];if(file){const fileId=crypto.randomUUID();await putFile(fileId,file);l.mediaId=fileId;l.url=URL.createObjectURL(file);l.fileName=file.name}else if(existing?.mediaId&&!f.url){l.mediaId=existing.mediaId;l.url=existing.url}if(index<0)draftCourse.lessons.push(l);else draftCourse.lessons[index]=l;$('#dialog').close();render();toast('Lesson updated. Save the course to keep your changes.');break}
case 'workshop-form':{const w={...draftWorkshop,...f,price:Number(f.price),original:Number(f.original),duration:Number(f.duration),capacity:Number(f.capacity),recording:!!f.recording,pointers:lines(f.pointers)};delete w._key;const {offer}=await platformRequest('admin-offer',{body:{kind:'workshop',...w}});const i=db.workshops.findIndex(x=>x.id===id);if(i<0)db.workshops.push(offer);else db.workshops[i]=offer;draftWorkshop=null;go('/admin/workshops');toast('Workshop and checkout price saved to Firebase.');break}
case 'mentorship-form':await platformRequest('mentorship-save',{body:{id,...f,price:Number(f.price),duration:Number(f.duration),pointers:lines(f.pointers)}});await refreshAccount();go('/admin/mentorship');toast('Mentorship offer saved to Firebase.');break;
case 'user-form':await platformRequest('user-access',{body:{id,existing:db.users.some(u=>u.id===id),name:f.name,email:f.email,role:form.dataset.team==='true'?f.role:'Learner',status:f.status,course:f.course||'',revokeManual:!!f.revokeManual}});await refreshAccount();$('#dialog').close();render();toast('Account access saved. The user can sign in with their Google email.');break;
case 'reschedule-form':await platformRequest('mentorship-update',{body:{id,date:f.date,time:f.time}});await refreshAccount();$('#dialog').close();render();toast('Reschedule request saved.');break;
case 'booking-status-form':await platformRequest('mentorship-update',{body:{id,status:f.status,meet:f.meet}});await refreshAccount();$('#dialog').close();render();toast('Session updated.');break;
case 'media-form':{const file=form.elements.image.files[0];const image=await readImage(file);if(!image)return;db.uploads??=[];db.uploads.push({file:image,original:file.name,bytes:file.size});save();$('#dialog').close();render();toast('Image added to your local library.');break}
case 'faq-form':{const value={q:f.q,a:f.a};if(Number(form.dataset.index)<0)db.faqs.push(value);else db.faqs[Number(form.dataset.index)]=value;save();$('#dialog').close();render();toast('FAQ saved. The public pages are updated.');break}
}}catch(err){console.error(err);toast('Couldn’t save that change. Browser storage may be unavailable.')}});
async function readImage(file){if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file.');return}if(file.size>2*1024*1024){toast('Choose an image smaller than 2MB for this demo.');return}return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}
document.addEventListener('change',async e=>{const el=e.target;try{if(el.id==='admin-status-filter'){tab=el.value;render()}if(el.id==='reward-select'){const total=Number($('[data-action="checkout"]').dataset.subtotal);$('#checkout-total').textContent=money(Math.round(total*(1-Number(el.value)/100)))}if(el.id==='profile-photo'){const image=await readImage(el.files[0]);if(image){db.profile.image=image;$('#profile-preview').src=image;toast('Photo selected. Save your profile to keep it.')}}if(el.id==='course-cover'){captureCourse();const image=await readImage(el.files[0]);if(image){draftCourse.image=image;render();toast('Cover selected. Save your course to keep it.')}}if(el.id==='workshop-photo'){const image=await readImage(el.files[0]);if(image){const f=formValues($('#workshop-form'));Object.assign(draftWorkshop,f,{pointers:lines(f.pointers),recording:!!f.recording,photo:image});render();toast('Tutor photo selected. Save the workshop to keep it.')}}}catch(err){console.error(err);toast('The file could not be loaded.')}});
let searchDelay;document.addEventListener('input',e=>{if(e.target.name==='message'&&e.target.form?.dataset.emailDelivery==='formsubmit')e.target.setCustomValidity('');if(['course-search','admin-course-search'].includes(e.target.id)){const el=e.target,id=el.id,pos=el.selectionStart;courseSearch=el.value;clearTimeout(searchDelay);searchDelay=setTimeout(()=>{render();const input=$('#'+id);input?.focus();input?.setSelectionRange(pos,pos)},180)}});
let dragIndex=-1;document.addEventListener('dragstart',e=>{const item=e.target.closest('.curriculum-item');if(item){captureCourse();dragIndex=Number(item.dataset.index);e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',String(dragIndex));item.classList.add('dragging')}});document.addEventListener('dragover',e=>{if(e.target.closest('.curriculum-item'))e.preventDefault()});document.addEventListener('drop',e=>{const item=e.target.closest('.curriculum-item');if(item&&dragIndex>=0){e.preventDefault();const to=Number(item.dataset.index),[moved]=draftCourse.lessons.splice(dragIndex,1);draftCourse.lessons.splice(to,0,moved);dragIndex=-1;render();toast('Lesson order updated. Save the course to keep it.')}});document.addEventListener('dragend',()=>document.querySelectorAll('.dragging').forEach(x=>x.classList.remove('dragging')));
document.addEventListener('visibilitychange',()=>{if(document.hidden&&timer.running&&timer.phase==='focus'){timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.running=false;if(route()==='/learner/momentum')render();toast('Focus paused while you’re away. Pick it up when you’re ready.')}});
document.addEventListener('click',e=>{const anchor=e.target.closest('a[href^="/"]');if(anchor&&$('#dialog').open)$('#dialog').close()});

function applyOffers(offers){const privateCourses=new Map(db.courses.filter(c=>loadedCourses.has(c.id)).map(c=>[c.id,c]));db.courses=offers.filter(o=>o.kind==='course').map(o=>loadedCourses.has(o.id)?{...privateCourses.get(o.id),...o,lessons:privateCourses.get(o.id).lessons,quiz:privateCourses.get(o.id).quiz}:o);db.workshops=offers.filter(o=>o.kind==='workshop');}
function mapOrders(orders){return orders.map(o=>({id:o.id,title:o.items.map(i=>i.title).join(', '),date:o.createdAt,amount:o.amount/100,status:o.status,paymentId:o.paymentId||'',mode:o.mode,verifiedAt:o.verifiedAt||''}));}
const verificationCache=new Map(),verificationLoading=new Set();
async function loadDiscussion(id){if(!id)return;const data=await platformRequest('discussion',{query:{courseId:id}});db.comments=data.comments;}
function applyWorkspace(w){if(!w)return;for(const key of ['activity','completed','quizPassed','notes','submissions','certificates','mentorships'])db[key]=w[key]??db[key];if(w.profile)db.profile={...db.profile,...w.profile,email:currentUser.email,image:currentUser.photoURL||''};if(w.comments)db.comments=w.comments;if(w.users)db.users=w.users;db.bookings.push(...(w.mentorshipBookings||[]));}
async function refreshAccount(){if(!currentUser)return;const requestedUid=currentUser.uid;const data=await platformRequest('account');if(currentUser?.uid!==requestedUid)return;lastWorkspaceSync=Date.now();role=data.user.role;const owned=new Map((data.ownedOffers||[]).map(o=>[o.kind+':'+o.id,o]));for(const o of [...db.courses.map(c=>({kind:'course',...c})),...db.workshops.map(w=>({kind:'workshop',...w}))])if(!owned.has(o.kind+':'+o.id))owned.set(o.kind+':'+o.id,o);applyOffers([...owned.values()]);db.profile={...db.profile,name:data.user.name,email:data.user.email,image:currentUser.photoURL||''};db.enrolled=data.enrolled.filter(e=>e.kind==='course').map(e=>e.offerId);db.bookings=data.enrolled.filter(e=>e.kind==='workshop').map(e=>({id:e.id,type:'workshop',offerId:e.offerId,title:e.title,status:'Paid',date:wBy(e.offerId)?.date||''}));applyWorkspace(data.workspace);db.transactions=mapOrders(data.orders);paymentHistoryCursor=data.nextCursor;if(['admin','super'].includes(role)){const [catalog,orders]=await Promise.all([platformRequest('admin-catalogue'),platformRequest('admin-orders')]);applyOffers(catalog.offers);db.transactions=mapOrders(orders.orders);paymentHistoryCursor=null;}for(const id of [...loadedCourses])if(role==='learner'&&!db.enrolled.includes(id)){loadedCourses.delete(id);const c=cBy(id);if(c){c.lessons=c.lessons.map(({id,title,section,type,minutes})=>({id,title,section,type,minutes}));delete c.quiz;}}return data;}
async function refreshCatalogue(){const mentorship=await platformRequest('mentorship-offers');db.mentorships=mentorship.offers;const {offers}=await platformRequest('catalogue');if(!['admin','super'].includes(role))applyOffers(offers);}
async function loadCourse(id){if(loadingCourses.has(id))return;loadingCourses.add(id);try{const {course}=await platformRequest('course-content',{query:{id:'course:'+id}});const index=db.courses.findIndex(c=>c.id===id);if(index>=0)db.courses[index]=course;else db.courses.push(course);loadedCourses.add(id);await loadDiscussion(id);}catch(error){courseErrors.set(id,error.message);}finally{loadingCourses.delete(id);render();}}
async function finishSignIn(entryPath){await refreshAccount();const target=sessionStorage.getItem('muxion.returnTo');sessionStorage.removeItem('muxion.returnTo');go(signInDestination({entryPath,role,returnTo:target}));}
async function accountChanged(user){db.profile={name:user?.displayName||'Learner',email:user?.email||'',phone:'',bio:'',timezone:'Asia/Kolkata',image:user?.photoURL||''};loadedCourses.clear();loadingCourses.clear();courseErrors.clear();db.completed=[];db.quizPassed=[];db.notes={};db.comments=[];db.submissions={};db.certificates=[];db.users=[];role='';db.enrolled=[];db.transactions=[];db.bookings=[];try{await refreshCatalogue();if(user){await refreshAccount();razorpayReceipt=await latestPaymentReceipt().catch(()=>null);if(['/login','/login/admin','/signup'].includes(route())){const target=sessionStorage.getItem('muxion.returnTo');sessionStorage.removeItem('muxion.returnTo');go(signInDestination({entryPath:route(),role,returnTo:target}));}}else{db.profile={...db.profile,name:'Learner',email:'',phone:'',image:''};}}catch(error){toast(error.message);}render();}

let lastRoute='';
function render(){const r=route(),parts=r.split('/').filter(Boolean);let html;document.title=(r.startsWith('/admin')?'Teaching Studio':r.startsWith('/learner')?'Your Learning Space':r==='/'?'MUXION Build, Learn & Academy':r==='/build'?'MUXION Build':r==='/learn'?'MUXION Learn':'MUXION Academy')+' — Make your next move.';
if(r.startsWith('/learner')&&!currentUser){html=authPage('login')}else if(r.startsWith('/admin')&&!['admin','super'].includes(role)){html=authPage('admin')}else if(parts[0]==='learner'){switch(parts[1]){case undefined:html=learnerOverview();break;case 'courses':html=learnerCourses();break;case 'wishlist':html=learnerCourses(true);break;case 'learn':html=learnerPlayer(parts[2]);break;case 'momentum':html=momentum();break;case 'workshops':html=learnerEvents('workshops');break;case 'mentorship':html=learnerEvents('mentorship');break;case 'certificates':html=certificates();break;case 'payments':html=payments();break;case 'profile':html=profile();break;case 'settings':html=settings();break;case 'notifications':html=notifications();break;default:html=notFound()}}else if(parts[0]==='admin'){switch(parts[1]){case undefined:html=adminOverview();break;case 'courses':html=parts[2]?courseEditor(parts[2]):adminCourses();break;case 'workshops':html=parts[2]?workshopEditor(parts[2]):workshopList();break;case 'mentorship':html=mentorshipAdmin(parts[2]);break;case 'learners':html=usersPage();break;case 'team':html=usersPage(true);break;case 'orders':html=orders();break;case 'certificates':html=certificates(true);break;case 'discussions':html=discussions();break;case 'media':html=mediaPage();break;case 'content':html=contentPage();break;case 'enquiries':html=enquiries();break;case 'settings':html=settings(true);break;case 'notifications':html=notifications(true);break;default:html=notFound()}}else{switch(parts[0]){case undefined:html=publicPage(universeHome({link,btn,icon,buildHeroGraphic,buildScrollShowcase,buildHomeSections,portraits,testimonialSlider,testimonials,workTestimonials,socialPortfolioTeaser}));break;case 'social-work':html=publicPage(socialPortfolioPage());break;case 'academy':html=home();break;case 'courses':html=catalogue();break;case 'course':html=courseDetail(parts[1]);break;case 'workshops':html=workshops();break;case 'workshop':html=workshopDetail(parts[1]);break;case 'mentorship':html=parts[1]==='book'?booking():mentorship();break;case 'build':history.replaceState({},'','/');html=publicPage(universeHome({link,btn,icon,buildHeroGraphic,buildScrollShowcase,buildHomeSections,portraits,testimonialSlider,testimonials,workTestimonials,socialPortfolioTeaser}));break;case 'learn':html=learning();break;case 'about':html=about();break;case 'contact':html=contact();break;case 'login':html=authPage(parts[1]==='admin'?'admin':'login');break;case 'signup':html=authPage('signup');break;case 'forgot-password':html=authPage('forgot');break;case 'reset-password':html=authPage('reset');break;case 'checkout':html=parts[1]==='success'?checkoutSuccess():checkout(parts[1]==='workshop'?parts[2]:'');break;case 'verify':html=verify(parts[1]);break;case 'privacy':case 'terms':case 'refunds':html=legal(parts[0]);break;case 'page-map':html=pageMap();break;default:html=notFound()}}
$('#app').innerHTML=html;enhance();enhanceBuildScroll();enhanceSocialPortfolio();enhanceUniverse({link,icon});document.dispatchEvent(new Event('muxion:rendered'));if(lastRoute!==r){window.scrollTo(0,0);lastRoute=r} }
installRouter(()=>{tab='all';courseSearch='';filter='All disciplines';render()});
// Render the local page shell before waiting on remote media, Firestore, or payments.
// Those services can be slow or unavailable without making the whole site look broken.
render();
Promise.all([loadMedia(),hydrateFiles(),refreshCatalogue().catch(()=>{}),paymentConfiguration().then(c=>paymentConfig=c).catch(()=>{})])
  .then(()=>render())
  .catch(error=>{console.error('MUXION background startup failed:',error);});
initializeAccounts(accountChanged).catch(error=>toast('Sign-in unavailable: '+error.message));timerTick=setInterval(tick,1000);setInterval(()=>{if(!document.hidden)refreshCatalogue().then(()=>currentUser&&Date.now()-lastWorkspaceSync>300000?refreshAccount():null).then(()=>{if(!$('#dialog')?.open&&!document.querySelector('form[data-dirty="true"]')&&(!route().startsWith('/admin/')||route()==='/admin/orders'))render();}).catch(()=>{});},30000);

for(const event of ['input','change'])document.addEventListener(event,e=>{if(e.target.form)e.target.form.dataset.dirty='true';});
